[{"author_association":null,"body":"`WaitForKustomizationReady` now calls `kustomizationClient.Get` before the timeout `select`. When `timeoutCtx` is already done, this will return a wrapped context deadline/canceled error ("get flux kustomization status: ...") instead of the intended `ErrReconcileTimeout` (with `lastStatus`). To keep timeout behavior deterministic, check `timeoutCtx.Err()` / `timeoutCtx.Done()` before making the GET, or translate context deadline/cancel errors into `ErrReconcileTimeout` in this loop.
```suggestion
	for {
		// Ensure deterministic timeout behavior: if the timeout context is already
		// expired, return ErrReconcileTimeout (with lastStatus if available)
		if err := timeoutCtx.Err(); err != nil {
			if lastStatus != "" {
				return fmt.Errorf("%w: last status: %s", ErrReconcileTimeout, lastStatus)
			}

			return ErrReconcileTimeout
		}

		kustomization, err := kustomizationClient.Get(
			timeoutCtx,
			rootKustomizationName,
			metav1.GetOptions{},
		)
		if err != nil {
			// Translate context deadline/cancel errors from the GET into the
			// canonical ErrReconcileTimeout to keep behavior deterministic.
			if errors.Is(err, context.DeadlineExceeded) || errors.Is(err, context.Canceled) {
				if lastStatus != "" {
					return fmt.Errorf("%w: last status: %s", ErrReconcileTimeout, lastStatus)
				}

				return ErrReconcileTimeout
			}
