+name: Copilot SDK CI
+
+on:
+  workflow_dispatch:
+  pull_request:
+    paths:
+      - 'copilot-client/**'
+      - '.github/workflows/copilot-sdk-ci.yml'
+
+permissions:
+  contents: read
+
+concurrency:
+  group: copilot-sdk-ci-${{ github.ref }}
+  cancel-in-progress: true
+
+jobs:
+  test:
+    runs-on: ubuntu-latest
+    steps:
+      - name: Checkout code
+        uses: actions/checkout@93cb6efe18208431cddfb8368fd83d5badbf9bfd # v5
+
+      - name: Setup Node.js
+        uses: actions/setup-node@395ad3262231945c25e8478fd5baf05154b1d79f # v6
+        with:
+          node-version: '24'
+          cache: 'npm'
+          cache-dependency-path: copilot-client/package-lock.json
+
+      - name: Install Copilot CLI
+        run: |
+          # Read version from constants.go (skip commented lines)
+          COPILOT_VERSION=$(grep 'DefaultCopilotVersion Version = "' pkg/constants/constants.go | grep -v '^//' | grep -oP '"\K[^"]+')
+          echo "Installing Copilot CLI version: $COPILOT_VERSION"
+          npm install -g @github/copilot@$COPILOT_VERSION
+
+      - name: Start Copilot CLI as headless server
+        id: copilot_server
+        run: |
+          mkdir -p /tmp/copilot-logs
+          mkdir -p /tmp/copilot-server
+          
+          # Start copilot in server mode
+          copilot --server --port 8080 --log-level all --log-dir /tmp/copilot-logs > /tmp/copilot-server/output.log 2>&1 &
+          SERVER_PID=$!
+          echo "SERVER_PID=$SERVER_PID" >> $GITHUB_ENV
+          
+          # Wait for server to be ready
+          sleep 5
+          
+          # Check if server is running
+          if ! kill -0 $SERVER_PID 2>/dev/null; then
+            echo "Failed to start copilot server"
+            cat /tmp/copilot-server/output.log
+            exit 1
+          fi
+          
+          echo "Copilot server started with PID: $SERVER_PID"
+        env:
+          COPILOT_GITHUB_TOKEN: ${{ secrets.COPILOT_GITHUB_TOKEN }}
+          GITHUB_TOKEN: ${{ secrets.COPILOT_GITHUB_TOKEN }}
+
+      - name: Install copilot-client dependencies
+        run: |
+          cd copilot-client
+          npm ci
+
+      - name: Build copilot-client
+        run: |
+          cd copilot-client
+          npm run build
+
+      - name: Run copilot-client tests
+        run: |
+          cd copilot-client
+          npm test
+        env:
+          COPILOT_GITHUB_TOKEN: ${{ secrets.COPILOT_GITHUB_TOKEN }}
+
+      - name: Test copilot-client integration
+        run: |
+          cd copilot-client
+          
+          # Create test prompt
+          mkdir -p /tmp/test
+          echo "What is 2+2? Answer briefly." > /tmp/test/prompt.txt
+          
+          # Create configuration
+          cat > /tmp/test/config.json << 'EOF'
+          {
+            "promptFile": "/tmp/test/prompt.txt",
+            "eventLogFile": "/tmp/test/events.jsonl",
+            "cliUrl": "localhost:8080",
+            "session": {
+              "model": "gpt-5"
+            }
+          }
+          EOF
+          
+          # Run the client
+          DEBUG=copilot-client cat /tmp/test/config.json | node dist/cli.js
+          
+          # Verify event log was created
+          if [ ! -f /tmp/test/events.jsonl ]; then
+            echo "Event log file was not created"
+            exit 1
+          fi
+          
+          # Check that events were logged
+          EVENT_COUNT=$(wc -l < /tmp/test/events.jsonl)
+          echo "Number of events logged: $EVENT_COUNT"
+          
+          if [ "$EVENT_COUNT" -lt 3 ]; then
+            echo "Expected at least 3 events, got $EVENT_COUNT"
+            cat /tmp/test/events.jsonl
+            exit 1
+          fi
+          
+          echo "✓ Integration test passed"","duplicate_id_conflict":false,"event_at":"2026-02-14T04:38:03+00:00","event_key":"inline_comment:2806980533","event_type":"inline_comment","html_url":null,"id":"2806980533","in_reply_to_id":null,"is_feedback_candidate":true,"is_human":true,"line":null,"original_commit_id":"ca188fbeec170524717c6cbef91b90860aa27973","original_line":null,"original_position":120,"original_start_line":null,"path":".github/workflows/copilot-sdk-ci.yml","position":120,"pull_request_review_id":"3800805431","pull_request_url":"https://api.github.com/repos/github/gh-aw/pulls/15592","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/github/gh-aw/pull/15592","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-02-14T04:40:46Z","url":null,"user":"pelikhan","user_id":null,"user_type":"User"},{"author_association":null,"body":"@copilot echo server logs","body_updated_after_merge":false,"commit_id":"305641f6876b6111513a0e4ce8ebdf2c7428ab81","created_at":"2026-02-14T04:38:48Z","diff_hunk":"@@ -0,0 +1,147 @@
