+#!/usr/bin/env node
+/**
+ * Post-build script to copy compiled files to actions/setup/js
+ */
+import { readFileSync, writeFileSync, mkdirSync } from 'fs';
+import { join, dirname } from 'path';
+import { fileURLToPath } from 'url';
+
+const __filename = fileURLToPath(import.meta.url);
+const __dirname = dirname(__filename);
+
+const distDir = join(__dirname, '..', 'dist');
+const targetDir = join(__dirname, '..', '..', 'actions', 'setup', 'js');
+
+console.log('Copying compiled files to actions/setup/js...');
+
+// Read the compiled index.js
+const indexPath = join(distDir, 'index.js');
+const indexContent = readFileSync(indexPath, 'utf-8');
+
+// Convert to CommonJS format for actions/setup/js
+const cjsContent = `/**
+ * GitHub Copilot SDK Client
+ * Auto-generated from copilot-client TypeScript source
+ * DO NOT EDIT MANUALLY - changes will be overwritten
+ */
+${indexContent}`;
+
+// Write to actions/setup/js/copilot_client.cjs
+const targetPath = join(targetDir, 'copilot_client.cjs');
+writeFileSync(targetPath, cjsContent, 'utf-8');","duplicate_id_conflict":false,"event_at":"2026-02-14T04:42:32+00:00","event_key":"inline_comment:2806985764","event_type":"inline_comment","html_url":null,"id":"2806985764","in_reply_to_id":"2806968291","is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"2e632a2ab60fb37d10ad3440582edf670cc3daee","original_line":null,"original_position":31,"original_start_line":null,"path":"copilot-client/scripts/post-build.js","position":1,"pull_request_review_id":"3800819330","pull_request_url":"https://api.github.com/repos/github/gh-aw/pulls/15592","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/github/gh-aw/pull/15592","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-02-14T04:42:32Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"}]

