+            // the target document's CreateEntityReference method is called.
+
+            string xml = @"<!DOCTYPE doc [
+<!ENTITY test ""TestValue"">
+]>
+<root>&test;</root>";
+
+            XmlDocument doc = new XmlDocument();
+            doc.PreserveWhitespace = true;
+            doc.LoadXml(xml);
+
+            // Use C14N transform which internally uses CanonicalXmlDocument
+            XmlDsigC14NTransform transform = new XmlDsigC14NTransform();
+            transform.LoadInput(doc);
+            
+            Stream output = (Stream)transform.GetOutput();
+            string result = new StreamReader(output, Encoding.UTF8).ReadToEnd();
+            
+            // Entity should be expanded in canonical form
+            Assert.Contains("TestValue", result);
+            Assert.Contains("<root>", result);","duplicate_id_conflict":false,"event_at":"2025-12-10T22:51:24+00:00","event_key":"inline_comment:2608484430","event_type":"inline_comment","html_url":null,"id":"2608484430","in_reply_to_id":"2535832891","is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"18b32e46e5002d52f634f97c57ae991f98c2bdd7","original_line":null,"original_position":39,"original_start_line":null,"path":"src/libraries/System.Security.Cryptography.Xml/tests/CanonicalXmlEntityReferenceTest.cs","position":1,"pull_request_review_id":"3564815140","pull_request_url":"https://api.github.com/repos/dotnet/runtime/pulls/120640","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/dotnet/runtime/pull/120640","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2025-12-10T22:51:24Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"@copilot In these two tests, at least, you wrote a comment saying what the state "should" be, but did not verify that state.  You should verify the state, as that is the purpose of the tests.","body_updated_after_merge":false,"commit_id":"dc905675ee057afb56f98af37cec45d9a4be7761","created_at":"2026-01-09T17:30:35Z","diff_hunk":"@@ -36,5 +36,1321 @@ public static void DecryptWithCertificate_NotInStore()
