+                writer.WriteEntry(entry);
+            }
+            
+            // Read back the raw bytes to verify the header structure
+            archiveStream.Seek(0, SeekOrigin.Begin);
+            byte[] headerBytes = new byte[512];
+            archiveStream.ReadExactly(headerBytes);
