+import {ISerializer} from "./ISerializer";
+
+/**
+ * Serializer for JavaScript Date objects.
+ * Serializes a Date as an ISO 8601 string.
+ *
+ * @example
+ * ```json
+ * { "__type": "Date", "__value": "2023-01-01T00:00:00.000Z" }
+ * ```
+ */
+export class DateSerializer implements ISerializer {
+    readonly type = "Date";
+
+    serialize(value: Date): string {
+        return value.toISOString();
+    }
+
+    deserialize(value: string): Date {
+        return new Date(value);
+    }
+
+    test(value: any): boolean {
+        return value instanceof Date;
+    }
+}
+
+/**
+ * Serializer for JavaScript Set objects.
+ * Serializes a Set as an array of its values.
+ *
+ * @example
+ * ```json
+ * { "__type": "Set", "__value": [1, 2, 3] }
+ * ```
+ */
+export class SetSerializer implements ISerializer {
+    readonly type = "Set";
+
+    serialize(value: Set<any>): any[] {
+        return [...value];
+    }
+
+    deserialize(value: any[]): Set<any> {
+        return new Set(value);
+    }
+
+    test(value: any): boolean {
+        return value instanceof Set;
+    }
+}
+
+/**
+ * Serializer for JavaScript Map objects.
+ * Serializes a Map as an array of key-value pairs.
+ *
+ * @example
+ * ```json
+ * { "__type": "Map", "__value": [["key1", "value1"], ["key2", "value2"]] }
+ * ```
+ */
+export class MapSerializer implements ISerializer {
+    readonly type = "Map";
+
+    serialize(value: Map<any, any>): [any, any][] {
+        return [...value];
+    }
+
+    deserialize(value: [any, any][]): Map<any, any> {
+        return new Map(value);
+    }
+
+    test(value: any): boolean {
+        return value instanceof Map;
+    }
+}
+
+/**
+ * Serializer for JavaScript RegExp objects.
+ * Serializes a RegExp as an object with source and flags.
+ *
+ * @example
+ * ```json
+ * { "__type": "RegExp", "__value": { "source": "hello\\s+world", "flags": "gi" } }
+ * ```
+ */
+export class RegExpSerializer implements ISerializer {
+    readonly type = "RegExp";
+
+    serialize(value: RegExp): { source: string; flags: string } {
+        return {source: value.source, flags: value.flags};
+    }
+
+    deserialize(value: { source: string; flags: string }): RegExp {
+        return new RegExp(value.source, value.flags);
+    }
+
+    test(value: any): boolean {
+        return value instanceof RegExp;
+    }
+}
+
+/**
+ * Serializer for JavaScript BigInt values.
+ * Serializes a BigInt as a string representation.
+ *
+ * @example
+ * ```json
+ * { "__type": "BigInt", "__value": "9007199254740993" }
+ * ```
+ */
+export class BigIntSerializer implements ISerializer {
+    readonly type = "BigInt";
+
+    serialize(value: bigint): string {
+        return value.toString();
+    }
+
+    deserialize(value: string): bigint {
+        return BigInt(value);
+    }
+
+    test(value: any): boolean {
+        return typeof value === 'bigint';
+    }
+}
+
+/**
+ * Default serializers included with the JsonAdapter.
+ * Provides built-in support for Date, Set, Map, RegExp, and BigInt types.
+ *
+ * You can extend this list with your own serializers:
+ * ```typescript
+ * import { JsonAdapter, defaultSerializers, ISerializer } from 'node-json-db';
+ *
+ * const mySerializer: ISerializer = {
+ *   type: "MyType",
+ *   serialize: (value) => value.toJSON(),
+ *   deserialize: (value) => MyType.fromJSON(value),
+ *   test: (value) => value instanceof MyType,
+ * };
+ *
+ * const adapter = new JsonAdapter(fileAdapter, false, true, [...defaultSerializers, mySerializer]);
+ * ```
+ */
+export const defaultSerializers: ISerializer[] = [
+    new DateSerializer(),
+    new SetSerializer(),
+    new MapSerializer(),
+    new RegExpSerializer(),
+    new BigIntSerializer(),
+];","duplicate_id_conflict":false,"event_at":"2026-03-10T12:03:47+00:00","event_key":"inline_comment:2911276246","event_type":"inline_comment","html_url":null,"id":"2911276246","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"abfdf0f2e759e6be81d04e3fab3df5301ad22faf","original_line":null,"original_position":152,"original_start_line":null,"path":"src/adapter/data/Serializers.ts","position":1,"pull_request_review_id":"3921882849","pull_request_url":"https://api.github.com/repos/Belphemur/node-json-db/pulls/1136","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/belphemur/node-json-db/pull/1136","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-03-10T12:03:48Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"The README.md has not been updated to document the new serialization features introduced in this PR. This includes: the built-in support for `Set`, `Map`, `RegExp`, and `BigInt` types; the `ISerializer` interface for consumer extensibility; the `defaultSerializers` export; and the new `serializers` parameter on `JsonAdapter`. The PR introduces this as a significant feature and the PR description itself documents the consumer extensibility pattern, but none of this appears in the README. This leaves library consumers unable to discover or use these features from the documentation. A breaking change (Date serialization now uses `__type`/`__value` envelope) is also not documented in the README.","body_updated_after_merge":false,"commit_id":"ff62c966526bb8146e41a793356fbea73bc140f1","created_at":"2026-03-10T12:03:47Z","diff_hunk":"@@ -9,8 +9,10 @@ import {readLockAsync, writeLockAsync} from "./lock/Lock";
