+defmodule PortalWeb.UserpassControllerTest do
+  use PortalWeb.ConnCase, async: true
+
+  import Portal.AccountFixtures
+  import Portal.ActorFixtures
+  import Portal.AuthProviderFixtures
+
+  @password "TestPassword1234!"
+
+  setup do
+    account = account_fixture()
+    provider = userpass_provider_fixture(account: account)
+    password_hash = Portal.Crypto.hash(:argon2, @password)
+
+    {:ok, account: account, provider: provider, password_hash: password_hash}
+  end
+
+  defp create_actor_with_password(attrs, password_hash) do
+    actor = actor_fixture(attrs)
+
+    actor
+    |> Ecto.Changeset.change(password_hash: password_hash)
+    |> Portal.Repo.update!()
+  end
+
+  describe "sign_in/2" do
+    test "redirects with error when account does not exist", %{conn: conn} do
+      conn =
+        post(conn, ~p"/nonexistent-account/sign_in/userpass/#{Ecto.UUID.generate()}", %{
+          "userpass" => %{"idp_id" => "test@example.com", "secret" => @password}
+        })
+
+      assert redirected_to(conn) =~ "nonexistent-account"
+    end
+
+    test "redirects with error for invalid password", %{
+      conn: conn,
+      account: account,
+      provider: provider,
+      password_hash: password_hash
+    } do
+      actor =
+        create_actor_with_password(
+          %{type: :account_admin_user, account: account},
+          password_hash
+        )
+
+      conn =
+        post(conn, ~p"/#{account.id}/sign_in/userpass/#{provider.id}", %{
+          "userpass" => %{"idp_id" => actor.email, "secret" => "wrong-password"}
+        })
+
+      assert redirected_to(conn) =~ "/sign_in/userpass/#{provider.id}"
+      assert flash(conn, :error) =~ "Invalid username or password"
+    end
+
+    test "successfully authenticates admin user in portal context", %{
+      conn: conn,
+      account: account,
+      provider: provider,
+      password_hash: password_hash
+    } do
+      actor =
+        create_actor_with_password(
+          %{type: :account_admin_user, account: account},
+          password_hash
+        )
+
+      conn =
+        post(conn, ~p"/#{account.id}/sign_in/userpass/#{provider.id}", %{
+          "userpass" => %{"idp_id" => actor.email, "secret" => @password}
+        })
+
+      assert redirected_to(conn) =~ "/sites"
+    end
+
+    test "rejects account_user in portal context", %{
+      conn: conn,
+      account: account,
+      provider: provider,
+      password_hash: password_hash
+    } do
+      actor =
+        create_actor_with_password(
+          %{type: :account_user, account: account},
+          password_hash
+        )
+
+      conn =
+        post(conn, ~p"/#{account.id}/sign_in/userpass/#{provider.id}", %{
+          "userpass" => %{"idp_id" => actor.email, "secret" => @password}
+        })
+
+      assert redirected_to(conn) =~ "/#{account.id}"
+      assert flash(conn, :error) =~ "admin privileges"
+    end
+
+    test "successfully authenticates admin user in client context", %{
+      conn: conn,
+      account: account,
+      provider: provider,
+      password_hash: password_hash
+    } do
+      actor =
+        create_actor_with_password(
+          %{type: :account_admin_user, account: account},
+          password_hash
+        )
+
+      conn =
+        post(conn, ~p"/#{account.id}/sign_in/userpass/#{provider.id}", %{
+          "userpass" => %{"idp_id" => actor.email, "secret" => @password},
+          "as" => "client",
+          "state" => "test-state",
+          "nonce" => "test-nonce"
+        })
+
+      assert conn.status == 200
+      assert conn.resp_body =~ "client_redirect"
+    end
+
+    test "successfully authenticates account_user in client context", %{
+      conn: conn,
+      account: account,
+      provider: provider,
+      password_hash: password_hash
+    } do
+      actor =
+        create_actor_with_password(
+          %{type: :account_user, account: account},
+          password_hash
+        )
+
+      conn =
+        post(conn, ~p"/#{account.id}/sign_in/userpass/#{provider.id}", %{
+          "userpass" => %{"idp_id" => actor.email, "secret" => @password},
+          "as" => "client",
+          "state" => "test-state",
+          "nonce" => "test-nonce"
+        })
+
+      assert conn.status == 200
+      assert conn.resp_body =~ "client_redirect"
+    end
+
+    test "successfully authenticates admin user in gui-client context", %{
+      conn: conn,
+      account: account,
+      provider: provider,
+      password_hash: password_hash
+    } do
+      actor =
+        create_actor_with_password(
+          %{type: :account_admin_user, account: account},
+          password_hash
+        )
+
+      conn =
+        post(conn, ~p"/#{account.id}/sign_in/userpass/#{provider.id}", %{
+          "userpass" => %{"idp_id" => actor.email, "secret" => @password},
+          "as" => "gui-client",
+          "state" => "test-state",
+          "nonce" => "test-nonce"
+        })
+
+      assert conn.status == 200
+      assert conn.resp_body =~ "client_redirect"
+    end
+
+    test "successfully authenticates admin user in headless-client context", %{
+      conn: conn,
+      account: account,
+      provider: provider,
+      password_hash: password_hash
+    } do
+      actor =
+        create_actor_with_password(
+          %{type: :account_admin_user, account: account},
+          password_hash
+        )
+
+      conn =
+        post(conn, ~p"/#{account.id}/sign_in/userpass/#{provider.id}", %{
+          "userpass" => %{"idp_id" => actor.email, "secret" => @password},
+          "as" => "headless-client",
+          "state" => "test-state"
+        })
+
+      assert conn.status == 200
+      assert conn.resp_body =~ "Copy token to clipboard"
+      assert conn.resp_body =~ actor.name
+    end
+
+    test "successfully authenticates account_user in headless-client context", %{
+      conn: conn,
+      account: account,
+      provider: provider,
+      password_hash: password_hash
+    } do
+      actor =
+        create_actor_with_password(
+          %{type: :account_user, account: account},
+          password_hash
+        )
+
+      conn =
+        post(conn, ~p"/#{account.id}/sign_in/userpass/#{provider.id}", %{
+          "userpass" => %{"idp_id" => actor.email, "secret" => @password},
+          "as" => "headless-client",
+          "state" => "test-state"
+        })
+
+      assert conn.status == 200
+      assert conn.resp_body =~ "Copy token to clipboard"
+    end
+
+    test "rejects account_user in gui-client context when using gui-client param", %{
+      conn: conn,
+      account: account,
+      provider: provider,
+      password_hash: password_hash
+    } do
+      actor =
+        create_actor_with_password(
+          %{type: :account_user, account: account},
+          password_hash
+        )
+
+      conn =
+        post(conn, ~p"/#{account.id}/sign_in/userpass/#{provider.id}", %{
+          "userpass" => %{"idp_id" => actor.email, "secret" => @password},
+          "as" => "gui-client",
+          "state" => "test-state",
+          "nonce" => "test-nonce"
+        })
+
+      # account_user should be allowed in gui-client context
+      assert conn.status == 200
+      assert conn.resp_body =~ "client_redirect"
+    end","duplicate_id_conflict":false,"event_at":"2026-01-26T14:06:48+00:00","event_key":"inline_comment:2727746457","event_type":"inline_comment","html_url":null,"id":"2727746457","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"3d39204f5fd87eb1ae5a38561a62b6d43eeb68be","original_line":null,"original_position":240,"original_start_line":null,"path":"elixir/test/portal_web/controllers/userpass_controller_test.exs","position":240,"pull_request_review_id":"3706200726","pull_request_url":"https://api.github.com/repos/firezone/firezone/pulls/11799","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/firezone/firezone/pull/11799","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-01-26T14:06:48Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"}]

