+
+        // Test cache creation with named pool
+        $cache2 = $this->builder->getCache('test-pool');
+        $this->assertInstanceOf(Cache::class, $cache2);
+
+        // Verify different pools create different instances
+        $this->assertNotSame($cache1, $cache2);
+    }
