+Describe "Packaging Module Functions" {
+    BeforeAll {
+        Import-Module $PSScriptRoot/../../build.psm1 -Force
+        Import-Module $PSScriptRoot/../../tools/packaging/packaging.psm1 -Force
+    }
+
+    Context "Test-IsPreview function" {
+        It "Should return True for preview versions" {
+            Test-IsPreview -Version "7.6.0-preview.6" | Should -Be $true
+            Test-IsPreview -Version "7.5.0-rc.1" | Should -Be $true
+            Test-IsPreview -Version "7.4.0-preview.1" | Should -Be $true
+        }
+
+        It "Should return False for stable versions" {
+            Test-IsPreview -Version "7.6.0" | Should -Be $false
+            Test-IsPreview -Version "7.5.0" | Should -Be $false
+            Test-IsPreview -Version "7.4.13" | Should -Be $false
+        }
+
+        It "Should return False for LTS builds regardless of version string" {
+            Test-IsPreview -Version "7.6.0-preview.6" -IsLTS | Should -Be $false
+            Test-IsPreview -Version "7.4.0-rc.1" -IsLTS | Should -Be $false
+            Test-IsPreview -Version "7.5.0" -IsLTS | Should -Be $false
+        }
+    }
+
+    Context "Get-MacOSPackageId function" {
+        It "Should return preview identifier when -IsPreview is specified" {
+            $result = Get-MacOSPackageId -IsPreview
+            $result | Should -Be "com.microsoft.powershell-preview"
+        }
+
+        It "Should return stable identifier when -IsPreview is not specified" {
+            $result = Get-MacOSPackageId
+            $result | Should -Be "com.microsoft.powershell"
+        }
+    }
+
+    Context "macOS preview package identifier detection" {
+        It "Should correctly detect preview from version string for preview builds" {
+            # Simulate the logic used in New-MacOSPackage","duplicate_id_conflict":false,"event_at":"2026-01-14T19:37:37+00:00","event_key":"inline_comment:2691779385","event_type":"inline_comment","html_url":null,"id":"2691779385","in_reply_to_id":null,"is_feedback_candidate":true,"is_human":true,"line":null,"original_commit_id":"e8ce89c09234d42e61c7a84783819f0bcb423aa9","original_line":null,"original_position":44,"original_start_line":null,"path":"test/packaging/packaging.tests.ps1","position":1,"pull_request_review_id":"3662435822","pull_request_url":"https://api.github.com/repos/PowerShell/PowerShell/pulls/26690","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/powershell/powershell/pull/26690","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-01-14T19:37:37Z","url":null,"user":"TravisEz13","user_id":null,"user_type":"User"},{"author_association":null,"body":"Added integration tests that verify `New-MacOSPackage` uses the correct logic. The new tests validate that the function calls `Test-IsPreview` with the `Version` and `LTS` parameters, and demonstrate the difference between the buggy logic (checking `$Name`) and the fixed logic (using `Test-IsPreview`). All 13 tests passing. (commit 409217b)","body_updated_after_merge":false,"commit_id":"409217b79f2193ef9bf869fd55b252d7ef790684","created_at":"2026-01-14T19:44:11Z","diff_hunk":"@@ -0,0 +1,104 @@
