+    .DESCRIPTION
+        This function determines if a package is a preview build based on the version string
+        and LTS flag, then returns the appropriate package identifier.
+    .PARAMETER Version
+        The version string (e.g., "7.6.0-preview.6" or "7.6.0")
+    .PARAMETER LTS
+        Whether this is an LTS build
+    .OUTPUTS
+        Hashtable with IsPreview (boolean) and PackageIdentifier (string) properties
+    .EXAMPLE
+        Get-MacOSPackageIdentifierInfo -Version "7.6.0-preview.6" -LTS:$false
+        Returns @{ IsPreview = $true; PackageIdentifier = "com.microsoft.powershell-preview" }
+#>
+function Get-MacOSPackageIdentifierInfo
+{
+    param(
+        [Parameter(Mandatory)]
+        [string]$Version,
+        
+        [switch]$LTS
+    )
+    
+    $IsPreview = Test-IsPreview -Version $Version -IsLTS:$LTS
+    $PackageIdentifier = Get-MacOSPackageId -IsPreview:$IsPreview","duplicate_id_conflict":false,"event_at":"2026-01-14T19:56:12+00:00","event_key":"inline_comment:2691841767","event_type":"inline_comment","html_url":null,"id":"2691841767","in_reply_to_id":null,"is_feedback_candidate":true,"is_human":true,"line":null,"original_commit_id":"0d1af8ea5467d73bd73849a7680198f28dae4b35","original_line":null,"original_position":71,"original_start_line":null,"path":"tools/packaging/packaging.psm1","position":1,"pull_request_review_id":"3662519479","pull_request_url":"https://api.github.com/repos/PowerShell/PowerShell/pulls/26690","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/powershell/powershell/pull/26690","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-01-14T19:56:12Z","url":null,"user":"TravisEz13","user_id":null,"user_type":"User"},{"author_association":null,"body":"Removed `Get-MacOSPackageId` and inlined its logic into `Get-MacOSPackageIdentifierInfo`. Updated `New-MacOSLauncher` to use the centralized function. Updated `New-MacOsDistributionPackage` to inline the simple logic. All package identifier logic is now centralized in one testable function. (commit 808ffb2)","body_updated_after_merge":false,"commit_id":"0d1af8ea5467d73bd73849a7680198f28dae4b35","created_at":"2026-01-14T20:00:59Z","diff_hunk":"@@ -2309,6 +2314,40 @@ function Get-MacOSPackageId
     }
 }

+<#
+    .SYNOPSIS
+        Determines the package identifier and preview status for macOS packages.
+    .DESCRIPTION
+        This function determines if a package is a preview build based on the version string
+        and LTS flag, then returns the appropriate package identifier.
+    .PARAMETER Version
+        The version string (e.g., "7.6.0-preview.6" or "7.6.0")
+    .PARAMETER LTS
+        Whether this is an LTS build
+    .OUTPUTS
+        Hashtable with IsPreview (boolean) and PackageIdentifier (string) properties
+    .EXAMPLE
+        Get-MacOSPackageIdentifierInfo -Version "7.6.0-preview.6" -LTS:$false
+        Returns @{ IsPreview = $true; PackageIdentifier = "com.microsoft.powershell-preview" }
+#>
+function Get-MacOSPackageIdentifierInfo
+{
+    param(
+        [Parameter(Mandatory)]
+        [string]$Version,
+        
+        [switch]$LTS
+    )
+    
+    $IsPreview = Test-IsPreview -Version $Version -IsLTS:$LTS
+    $PackageIdentifier = Get-MacOSPackageId -IsPreview:$IsPreview","duplicate_id_conflict":false,"event_at":"2026-01-14T20:00:59+00:00","event_key":"inline_comment:2691856120","event_type":"inline_comment","html_url":null,"id":"2691856120","in_reply_to_id":"2691841767","is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"0d1af8ea5467d73bd73849a7680198f28dae4b35","original_line":null,"original_position":71,"original_start_line":null,"path":"tools/packaging/packaging.psm1","position":1,"pull_request_review_id":"3662537310","pull_request_url":"https://api.github.com/repos/PowerShell/PowerShell/pulls/26690","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/powershell/powershell/pull/26690","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-01-14T20:00:59Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"}]

