+				_contentView.TrailingAnchor.ConstraintEqualTo(NativeView.TrailingAnchor),
+				_contentView.TopAnchor.ConstraintEqualTo(NativeView.TopAnchor),
+				_contentView.BottomAnchor.ConstraintEqualTo(NativeView.BottomAnchor),
