+		switch (horizontalAlignment)
+		{
+			case LayoutAlignment.Fill:
+				if (widthRequest >= 0)
+				{
+					constraints.Add(child.LeadingAnchor.ConstraintEqualTo(parent.LeadingAnchor, marginLeft));
+					constraints.Add(child.WidthAnchor.ConstraintEqualTo((nfloat)widthRequest));
+				}
+				else
+				{
+					constraints.Add(child.LeadingAnchor.ConstraintEqualTo(parent.LeadingAnchor, marginLeft));
+					constraints.Add(parent.TrailingAnchor.ConstraintEqualTo(child.TrailingAnchor, marginRight));
+				}
+				break;
+			case LayoutAlignment.Center:
+				constraints.Add(child.CenterXAnchor.ConstraintEqualTo(parent.CenterXAnchor, (marginLeft - marginRight) / 2));
+				if (widthRequest >= 0)
+					constraints.Add(child.WidthAnchor.ConstraintEqualTo((nfloat)widthRequest));
+				break;
+			case LayoutAlignment.Start:
+				constraints.Add(child.LeadingAnchor.ConstraintEqualTo(parent.LeadingAnchor, marginLeft));
+				if (widthRequest >= 0)
+					constraints.Add(child.WidthAnchor.ConstraintEqualTo((nfloat)widthRequest));
+				break;
+			case LayoutAlignment.End:
+				constraints.Add(parent.TrailingAnchor.ConstraintEqualTo(child.TrailingAnchor, marginRight));
+				if (widthRequest >= 0)
+					constraints.Add(child.WidthAnchor.ConstraintEqualTo((nfloat)widthRequest));
+				break;
+		}
+
+		// Vertical
+		switch (verticalAlignment)
+		{
+			case LayoutAlignment.Fill:
+				if (heightRequest >= 0)
+				{
+					constraints.Add(child.TopAnchor.ConstraintEqualTo(parent.TopAnchor, marginTop));
+					constraints.Add(child.HeightAnchor.ConstraintEqualTo((nfloat)heightRequest));
+				}
+				else
+				{
+					constraints.Add(child.TopAnchor.ConstraintEqualTo(parent.TopAnchor, marginTop));
+					constraints.Add(parent.BottomAnchor.ConstraintEqualTo(child.BottomAnchor, marginBottom));
+				}
+				break;
+			case LayoutAlignment.Center:
+				constraints.Add(child.CenterYAnchor.ConstraintEqualTo(parent.CenterYAnchor, (marginTop - marginBottom) / 2));
+				if (heightRequest >= 0)
+					constraints.Add(child.HeightAnchor.ConstraintEqualTo((nfloat)heightRequest));
+				break;
+			case LayoutAlignment.Start:
+				constraints.Add(child.TopAnchor.ConstraintEqualTo(parent.TopAnchor, marginTop));
+				if (heightRequest >= 0)
+					constraints.Add(child.HeightAnchor.ConstraintEqualTo((nfloat)heightRequest));
+				break;
+			case LayoutAlignment.End:
+				constraints.Add(parent.BottomAnchor.ConstraintEqualTo(child.BottomAnchor, marginBottom));
+				if (heightRequest >= 0)
+					constraints.Add(child.HeightAnchor.ConstraintEqualTo((nfloat)heightRequest));","duplicate_id_conflict":false,"event_at":"2026-02-20T18:35:48+00:00","event_key":"inline_comment:2834586363","event_type":"inline_comment","html_url":null,"id":"2834586363","in_reply_to_id":"2834508649","is_feedback_candidate":true,"is_human":true,"line":null,"original_commit_id":"b8e571b6e8e057ad6c9218ab59b985b173f53750","original_line":null,"original_position":154,"original_start_line":null,"path":"src/Spice/Platforms/iOS/ConstraintHelper.cs","position":1,"pull_request_review_id":"3833652962","pull_request_url":"https://api.github.com/repos/jonathanpeppers/spice/pulls/124","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/jonathanpeppers/spice/pull/124","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-02-20T18:35:48Z","url":null,"user":"jonathanpeppers","user_id":null,"user_type":"User"}]

