[{"author_association":null,"body":"@copilot Remove the `WithNoFixCompilation`, all tests in this file must compile. Be sure to target C# 14 if needed","body_updated_after_merge":false,"commit_id":"b76f34a7f533eb9b0aa56f3abd5f088c3670f30c","created_at":"2026-02-19T02:43:15Z","diff_hunk":"@@ -1177,6 +1177,133 @@ void A()
             .ValidateAsync();
     }

+    [Fact]
+    public async Task PropertyInitializer_RemoveAndReplaceWithProperty_PartialProperty()
+    {
+        const string SourceCode = """
+using System;
+using System.Text.RegularExpressions;
+
+class Sample
+{
+    public Regex SampleRegex { get; } = [||]new Regex("pattern");
+
+    void M()
+    {
+        _ = SampleRegex.IsMatch("value");
+    }
+}
+""";
+
+        const string CodeFix = """
+using System;
+using System.Text.RegularExpressions;
+
+partial class Sample
+{
+
+    void M()
+    {
+        _ = SampleRegex.IsMatch("value");
+    }
+
+    [GeneratedRegex("pattern")]
+    private static partial Regex SampleRegex { get; }
+}
+""";
+
+        await new ProjectBuilder()
+            .WithTargetFramework(TargetFramework.Net7_0)
+            .WithLanguageVersion(Microsoft.CodeAnalysis.CSharp.LanguageVersion.CSharp14)
+            .WithAnalyzer<UseRegexSourceGeneratorAnalyzer>()
+            .WithCodeFixProvider<UseRegexSourceGeneratorFixer>()
+            .WithNoFixCompilation()","duplicate_id_conflict":false,"event_at":"2026-02-19T02:43:15+00:00","event_key":"inline_comment:2825413936","event_type":"inline_comment","html_url":null,"id":"2825413936","in_reply_to_id":null,"is_feedback_candidate":true,"is_human":true,"line":null,"original_commit_id":"b76f34a7f533eb9b0aa56f3abd5f088c3670f30c","original_line":null,"original_position":44,"original_start_line":null,"path":"tests/Meziantou.Analyzer.Test/Rules/UseRegexSourceGeneratorAnalyzerTests.cs","position":1,"pull_request_review_id":"3823219390","pull_request_url":"https://api.github.com/repos/meziantou/Meziantou.Analyzer/pulls/1014","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/meziantou/meziantou.analyzer/pull/1014","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-02-19T02:43:15Z","url":null,"user":"meziantou","user_id":null,"user_type":"User"},{"author_association":null,"body":"I've removed `.WithNoFixCompilation()` from the property initializer tests and wrapped them in `#if CSHARP14_OR_GREATER`. However, the tests fail because `GeneratedRegex` attribute requires the Regex source generator to run during compilation, which doesn't happen in unit tests.

The tests currently use partial methods (index 1) which keep the property and change the initializer to call a generated method. This approach compiles without the source generator, but still requires `.WithNoFixCompilation()` because the partial method needs an implementation.

Should I:
1. Add source generator support to the test infrastructure?
