        // Chain onto the existing lock promise to ensure mutual exclusion and single-flight behavior.
        // Any previous rejection is caught so it does not poison future lock acquisitions.
        const lockPromise = this.modelsCacheLock = this.modelsCacheLock
            .catch(() => {})
            .then(async () => {
                // Inside the critical section: check and populate the cache if needed.
                if (this.modelsCache === null) {
                    const result = await this.connection!.sendRequest("models.list", {});
                    const response = result as { models: ModelInfo[] };
                    const models = response.models;
                    this.modelsCache = models;
                }
            });

        // Wait for the critical section (including any in-flight fetch) to complete.
        await lockPromise;

        // At this point the cache should be populated unless the request failed,
        // in which case the error will have been thrown by await lockPromise above.
        if (this.modelsCache === null) {
