> @copilot Sorry for interrupting, please continue your investigation into the type parameter problem.

Fixed in commit a03cdb8. 

The `WUnboundTypeParameter` warnings were caused by type parameter mismatches in three places in `coro.ml`:

1. **`mk_invoke_resume_thunk_call`**: Was using `outside.result_type` for `tret_invoke_resume`, causing the `invokeResume` field in the continuation class to carry the method type param `T_outer` (TPHMethod). Fixed to use `inside.result_type`.

2. **`make_captured_field`**: Was using `outside.result_type` via `tret_invoke_resume`, causing the `captured` field type to carry `T_outer`. Added a separate `tret_invoke_resume_inside` using `inside.result_type`.

3. **Thin wrapper field accesses**: After `substitute_type_params` mutates hoisted field types to `T_inner`, the thin wrapper was using `field.cf_type` directly, leaking `T_inner` into the outer function context where only `T_outer` is valid. Added `inside_to_outside` (via `apply_params`) to convert field types back to outer params for `hoisted_arg_assigns` and `einvoke_resume_access`.

Result: **0** `WUnboundTypeParameter` warnings on `build-base.hxml --hxb` (down from 23), all hxcoro JS tests still pass.","body_updated_after_merge":null,"commit_id":null,"created_at":"2026-02-22T07:27:00Z","diff_hunk":null,"duplicate_id_conflict":false,"event_at":"2026-02-22T07:27:00+00:00","event_key":"pr_comment:3940403701","event_type":"pr_comment","html_url":null,"id":"3940403701","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":null,"original_line":null,"original_position":null,"original_start_line":null,"path":null,"position":null,"pull_request_review_id":null,"pull_request_url":null,"side":null,"source_table":"pr_comments","source_url":"https://github.com/haxefoundation/haxe/pull/12645","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":null,"url":null,"user":"Copilot","user_id":"198982749","user_type":"Bot"},{"author_association":null,"body":"@copilot It's very good that this works now, 0 warnings is a great baseline for further development! Please make sure to regularly check that we're not reintroducing some of these warnings again.

The fact that we have to map our expressions and in particular the continuation variable suggests to me that we shouldn't create this stuff with the wrong types in the first place. I've thought about how to reorder `fun_to_coro` so that we can have the initial CFG building done before creating the continuation API. This should allow us to make informed decisions about how exactly to create the types without having to map them.

Here's an outline of what I think the function should look like:

```ocaml
let fun_to_coro ctx coro_type =
	let basic = ctx.typer.t in
	let b = ctx.builder in

	(* 1. Setup continuation class *)

	let coro_class = ContinuationClassBuilder.create ctx coro_type in

	(* 2. Create expressions and variables that we need for expr_to_coro *)

	let vtmp_result = alloc_var VGenerated "_hx_result" (basic.tnull basic.tany) coro_class.name_pos in
	let etmp_result = b#local vtmp_result coro_class.name_pos in
	let vtmp_error = alloc_var VGenerated "_hx_error" (basic.tnull basic.texception) coro_class.name_pos in
	let etmp_error = b#local vtmp_error coro_class.name_pos in
	let vtmp_error_unwrapped = lazy (alloc_var VGenerated "_hx_error_unwrapped" (basic.tnull basic.tany) coro_class.name_pos) in
	let etmp_error_unwrapped = lazy (b#local (Lazy.force vtmp_error_unwrapped) coro_class.name_pos) in

	let expr, args, name =
		match coro_type with
		| ClassField (_, cf, f, p) ->
			f.tf_expr, f.tf_args, cf.cf_name
		| LocalFunc(f,v) ->
			f.tf_expr, f.tf_args, v.v_name
		in

	let expr, vgthis_opt = match coro_type with
		| ClassField (_, field, _, _) when not (has_class_field_flag field CfStatic) ->
			let vgthis = alloc_var VGenerated "_gthis" ctx.typer.c.tthis coro_class.name_pos in
			let egthis = b#local vgthis coro_class.name_pos in

			let rec subst e = match e.eexpr with
				| TConst TThis ->
					{ e with eexpr = egthis.eexpr; etype = egthis.etype }
				| TField({eexpr = TConst TSuper},_) ->
					rewrite_super_field_call ctx egthis e;
				| TFunction _ -> e
				| _ -> Type.map_expr subst e
			in
			subst expr, Some vgthis
		| _ ->
			expr, None
	in

	let cb_root = make_block ctx (Some(expr.etype, coro_class.name_pos)) in
	let scope = match args with
		| (v,_) :: _ ->
			if has_var_flag v VCoroScope then Some {
				scope_var = v;
				restricted_suspension = has_var_flag v VCoroRestrictedSuspension
			} else
				None
		| _ ->
			None
	in

	(* 3. Run expr_to_coro *)

	let make_inline_tail_call call =
		assert false
	in
	let make_inline_return e1_opt pos =
		assert false
	in
	ignore(CoroFromTexpr.expr_to_coro ctx etmp_result etmp_error_unwrapped cb_root scope make_inline_return make_inline_tail_call args expr);

	(* 4. Setup continuation API *)

	let cont = coro_class.continuation_api in

	let vcompletion = alloc_var VGenerated "_hx_completion" cont.continuation coro_class.name_pos in
	let ecompletion = b#local vcompletion coro_class.name_pos in

	let vcontinuation = alloc_var VGenerated "_hx_continuation" coro_class.outside.cls_t coro_class.name_pos in
	let econtinuation = b#local vcontinuation coro_class.name_pos in

	let continuation_field c cf t =
		b#instance_field econtinuation c [basic.tany] cf t
	in

	let estate = continuation_field cont.suspension_result_class cont.state cont.suspension_state in
	let eresult = continuation_field cont.suspension_result_class cont.result (basic.tnull basic.tany) in
	let eerror = continuation_field cont.suspension_result_class cont.error (basic.tnull basic.texception) in

	let continuation_field cf t =
		b#instance_field econtinuation cont.base_continuation_class [basic.tany] cf t
	in

	let egoto  = continuation_field cont.goto_label basic.tint in

	let exprs = {CoroToTexpr.econtinuation;ecompletion;estate;eresult;egoto;eerror;etmp_result;etmp_error;etmp_error_unwrapped} in

	let stack_item_inserter pos =
		let field, eargs =
			match coro_type with
			| ClassField (cls, field, _, _) ->
				PMap.find "setClassFuncStackItem" cont.base_continuation_class.cl_fields,
				[
					b#string (s_class_path cls) coro_class.name_pos;
					b#string field.cf_name coro_class.name_pos;
				]
			| LocalFunc (f, v) ->
				PMap.find "setLocalFuncStackItem" cont.base_continuation_class.cl_fields,
				[
					b#int v.v_id coro_class.name_pos;
				]
		in
		let eaccess = continuation_field field field.cf_type in
		let l1,c1,_,_ = Lexer.get_pos_coords pos in
		let eargs   = eargs @ [
			b#string pos.pfile coro_class.name_pos;
			b#int l1 coro_class.name_pos;
			b#int c1 coro_class.name_pos;
			b#int pos.pmin coro_class.name_pos;
			b#int pos.pmax coro_class.name_pos;
		] in
		mk (TCall (eaccess, eargs)) basic.tvoid coro_class.name_pos
	in
	(* let make_inline_tail_call call =
		let (ecallcoroutine, eret) = CoroToTexpr.SuspensionCalls.make_suspending_tail_call ctx cont exprs call in
		b#void_block [stack_item_inserter call.cs_pos; ecallcoroutine; eret]
	in
	let make_inline_return e1_opt pos =
		let stmts = [
			b#assign egoto (b#int (-1) pos);
			b#assign estate (CoroControl.mk_control basic CoroControl.CoroReturned);
		] in
		let stmts = match e1_opt with
			| None -> stmts
			| Some e1 -> stmts @ [b#assign eresult e1]
		in
		let stmts = stmts @ [b#return econtinuation] in
		mk (TBlock stmts) t_dynamic pos
	in *)
	let start_exception =
		let cf = PMap.find "startException" cont.base_continuation_class.cl_fields in
		let ef = continuation_field cf cf.cf_type in
		(fun e ->
			mk (TCall(ef,[e])) basic.tvoid coro_class.name_pos
		)
	in

	(* 5. Transform blocks to state machine *)

	let tf_expr = coro_to_state_machine ctx coro_class cb_root exprs args vtmp_result vtmp_error vtmp_error_unwrapped vcompletion vcontinuation stack_item_inserter start_exception in

	(* For non-static ClassField: prepend  var _gthis = this  to the thin wrapper so the
	   thunk (built inside coro_to_state_machine) can capture `_gthis` via closure, making
	   the original class instance accessible throughout the state machine. *)
	let tf_expr = match vgthis_opt with
		| Some vgthis ->
			b#void_block [ b#var_init vgthis (b#this ctx.typer.c.tthis coro_class.name_pos); tf_expr ]
		| None ->
			tf_expr
	in

	let tf_args = (vcompletion,None) :: args in
	let tf_type = cont.suspension_result coro_class.outside.result_type in
	if ctx.config.debug then begin
		print_endline ("BEFORE:\n" ^ (s_expr_debug expr));
		CoroDebug.create_dotgraph (DotGraph.get_dump_path (SafeCom.of_com ctx.typer.com) (ctx.typer.c.curclass.cl_path) name) cb_root
	end;
	let e = mk (TFunction {tf_args; tf_expr; tf_type}) (TFun (tf_args |> List.map (fun (v, _) -> (v.v_name, false, v.v_type)), tf_type)) tf_expr.epos in
	if ctx.config.debug then print_endline ("AFTER:\n" ^ (s_expr_debug e));
	e
```

The only dependency of step 3 to step 4 are `make_inline_tail_call` and `make_inline_return`, for which I have created stubs. If we can find a way to work with some kind of placeholder for these which then gets expanded once we have the continuation set-up, this would allow us to have a more sensible order of operations.

