+module.exports = async ({ github, context }) => {
+  const { owner, repo } = context.repo;
+  const pr = context.payload.pull_request.number;
+  const sha = context.payload.pull_request.head.sha;
+  const token = process.env.GITHUB_TOKEN;
+
+  const GENERATED = [
+    /^mlflow\/protos\/.*\.pyi$/,
+    /_pb2(_grpc)?\.py$/,
+    /^uv\.lock$/,
+    /package-lock\.json$/,
+    /yarn\.lock$/,
+    /^docs\/api_reference\/source\/rest-api\.rst$/,
+  ];
+
+  const THRESHOLDS = {
+    XS: 9,
+    S: 49,
+    M: 199,
+    L: 499,
+    XL: Infinity,
+  };
+
+  async function isGenerated(filename) {
+    if (GENERATED.some((p) => p.test(filename))) return true;
+    if (filename.endsWith(".java")) {
+      try {
+        const resp = await fetch(
+          `https://raw.githubusercontent.com/${owner}/${repo}/${sha}/${filename}`,
+          { headers: { Range: "bytes=0-255", Authorization: `token ${token}` } }
+        );
+        if (resp.ok) {
+          const text = await resp.text();
+          if (text.includes("Generated by the protocol buffer compiler")) return true;
+        }
+      } catch (e) {
+        console.warn(filename, e.message);
+      }
+    }
+    return false;
+  }
+
+  function getSize(total) {
+    return Object.entries(THRESHOLDS).find(([, max]) => total <= max)[0];
+  }
+
+  async function calculateSize() {
+    let total = 0;
+    const maxThreshold = Math.max(...Object.values(THRESHOLDS).filter(isFinite));
+    for (let page = 1; ; page++) {
+      const files = await github.rest.pulls.listFiles({
+        owner,
+        repo,
+        pull_number: pr,
+        per_page: 100,
+        page,
+      });
+      const done = files.data.length < 100;
+      for (const f of files.data) {
+        if (!(await isGenerated(f.filename))) {
+          total += f.additions + f.deletions;
+        }
+      }
+      if (done || total > maxThreshold) break;
+    }
+    return getSize(total);
+  }
+
+  async function ensureLabelExists(labelName) {
+    try {
+      await github.rest.issues.getLabel({
+        owner,
+        repo,
+        name: labelName,
+      });
+      console.log(`Label ${labelName} exists`);
+    } catch (error) {
+      if (error.status === 404) {
+        console.log(`Label ${labelName} does not exist, creating it`);
+        await github.rest.issues.createLabel({
+          owner,
+          repo,
+          name: labelName,
+          color: "ededed",
+        });
+        console.log(`Label ${labelName} created`);
+      } else {
+        throw error;
+      }
+    }
+  }
+
+  const size = await calculateSize();
+  const sizeLabel = `size/${size}`;
+  console.log(`Calculated size label: ${sizeLabel}`);
+
+  // Get existing labels on the PR
+  const existingLabels = await github.rest.issues.listLabelsOnIssue({
+    owner,
+    repo,
+    issue_number: pr,
+  });
+  const existingLabelNames = existingLabels.data.map(({ name }) => name);","duplicate_id_conflict":false,"event_at":"2026-02-15T03:44:12+00:00","event_key":"inline_comment:2808465216","event_type":"inline_comment","html_url":null,"id":"2808465216","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"5f35eb154f32637659b93a8590ee3d1494bcc280","original_line":null,"original_position":103,"original_start_line":null,"path":".github/workflows/pr-size.js","position":1,"pull_request_review_id":"3803329437","pull_request_url":"https://api.github.com/repos/mlflow/mlflow/pulls/20820","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/mlflow/mlflow/pull/20820","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-02-15T03:44:14Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"This fetch always sends an `Authorization` header using `process.env.GITHUB_TOKEN`, but in `actions/github-script` that env var is often unset. Sending `Authorization: token undefined` can cause GitHub to return 401 even for public content, which would make the generated-Java detection always fail and inflate PR size. Either pass the token via workflow `env` (e.g. `GITHUB_TOKEN: ${{ github.token }}`) or only include the Authorization header when a token is present.
```suggestion
        const headers = { Range: "bytes=0-255" };
        if (token) {
          headers.Authorization = `token ${token}`;
        }
        const resp = await fetch(
          `https://raw.githubusercontent.com/${owner}/${repo}/${sha}/${filename}`,
          { headers }
