        try {
          await github.rest.issues.createLabel({
            owner,
            repo,
            name: labelName,
            color: "ededed",
          });
          console.log(`Label ${labelName} created`);
        } catch (createError) {
          if (createError.status === 422) {
            // Label was likely created by a concurrent workflow run; treat as success.
            console.log(`Label ${labelName} already exists (created concurrently)`);
          } else {
            throw createError;
