+#include "iowatcher.h"
+
+#ifdef EVENT_IO_URING
+#include "hplatform.h"
+#include "hdef.h"
+#include "hevent.h"
+
+#include <liburing.h>
+#include <poll.h>
+
+#define IO_URING_ENTRIES    1024
+#define IO_URING_CANCEL_TAG UINT64_MAX
+
+typedef struct io_uring_ctx_s {
+    struct io_uring ring;
+    int             nfds;
+} io_uring_ctx_t;
+
+int iowatcher_init(hloop_t* loop) {
+    if (loop->iowatcher) return 0;
+    io_uring_ctx_t* ctx;
+    HV_ALLOC_SIZEOF(ctx);
+    int ret = io_uring_queue_init(IO_URING_ENTRIES, &ctx->ring, 0);
+    if (ret < 0) {
+        HV_FREE(ctx);
+        return ret;
+    }
+    ctx->nfds = 0;
+    loop->iowatcher = ctx;
+    return 0;
+}
+
+int iowatcher_cleanup(hloop_t* loop) {
+    if (loop->iowatcher == NULL) return 0;
+    io_uring_ctx_t* ctx = (io_uring_ctx_t*)loop->iowatcher;
+    io_uring_queue_exit(&ctx->ring);
+    HV_FREE(loop->iowatcher);
+    return 0;
+}
+
+int iowatcher_add_event(hloop_t* loop, int fd, int events) {
+    if (loop->iowatcher == NULL) {
+        iowatcher_init(loop);
+    }
+    io_uring_ctx_t* ctx = (io_uring_ctx_t*)loop->iowatcher;
+    hio_t* io = loop->ios.ptr[fd];
+
+    unsigned poll_mask = 0;
+    // pre events
+    if (io->events & HV_READ) {
+        poll_mask |= POLLIN;
+    }
+    if (io->events & HV_WRITE) {
+        poll_mask |= POLLOUT;
+    }
+    // now events
+    if (events & HV_READ) {
+        poll_mask |= POLLIN;
+    }
+    if (events & HV_WRITE) {
+        poll_mask |= POLLOUT;
+    }
+
+    struct io_uring_sqe* sqe;
+    if (io->events != 0) {
+        // Cancel the existing poll request first
+        sqe = io_uring_get_sqe(&ctx->ring);
+        if (sqe == NULL) return -1;
+        io_uring_prep_poll_remove(sqe, (uint64_t)fd);
+        io_uring_sqe_set_data64(sqe, IO_URING_CANCEL_TAG);
+    } else {
+        ctx->nfds++;
+    }
+
+    // Add poll for the combined events
+    sqe = io_uring_get_sqe(&ctx->ring);
+    if (sqe == NULL) return -1;
+    io_uring_prep_poll_add(sqe, fd, poll_mask);
+    io_uring_sqe_set_data64(sqe, (uint64_t)fd);","duplicate_id_conflict":false,"event_at":"2026-03-11T03:43:16+00:00","event_key":"inline_comment:2915677813","event_type":"inline_comment","html_url":null,"id":"2915677813","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"6113c3183dcee578d13c770437ec4979b3ff0304","original_line":null,"original_position":79,"original_start_line":null,"path":"event/io_uring.c","position":1,"pull_request_review_id":"3926689789","pull_request_url":"https://api.github.com/repos/ithewei/libhv/pulls/813","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/ithewei/libhv/pull/813","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-03-11T03:43:18Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"`iowatcher_del_event` returns -1 when `io_uring_get_sqe` fails, but `hio_del` doesn't check this and will still clear `io->events`. That can desynchronize the loop's idea of what is armed vs. what's actually registered in io_uring; handle SQE exhaustion here (submit/flush + retry) and avoid returning an unhandled error.","body_updated_after_merge":false,"commit_id":"800e9718436224495379c38c88542f725b210418","created_at":"2026-03-11T03:43:16Z","diff_hunk":"@@ -0,0 +1,209 @@
