+#include "iowatcher.h"
+
+#ifdef EVENT_IO_URING
+#include "hplatform.h"
+#include "hdef.h"
+#include "hevent.h"
+
+#include <liburing.h>
+#include <poll.h>
+
+#define IO_URING_ENTRIES    1024
+#define IO_URING_CANCEL_TAG UINT64_MAX
+
+typedef struct io_uring_ctx_s {
+    struct io_uring ring;
+    int             nfds;
+} io_uring_ctx_t;
+
+int iowatcher_init(hloop_t* loop) {
+    if (loop->iowatcher) return 0;
+    io_uring_ctx_t* ctx;
+    HV_ALLOC_SIZEOF(ctx);
+    int ret = io_uring_queue_init(IO_URING_ENTRIES, &ctx->ring, 0);
+    if (ret < 0) {
+        HV_FREE(ctx);
+        return ret;
+    }
+    ctx->nfds = 0;
+    loop->iowatcher = ctx;
+    return 0;
+}
+
+int iowatcher_cleanup(hloop_t* loop) {
+    if (loop->iowatcher == NULL) return 0;
+    io_uring_ctx_t* ctx = (io_uring_ctx_t*)loop->iowatcher;
+    io_uring_queue_exit(&ctx->ring);
+    HV_FREE(loop->iowatcher);
+    return 0;
+}
+
+int iowatcher_add_event(hloop_t* loop, int fd, int events) {
+    if (loop->iowatcher == NULL) {
+        iowatcher_init(loop);
+    }
+    io_uring_ctx_t* ctx = (io_uring_ctx_t*)loop->iowatcher;
+    hio_t* io = loop->ios.ptr[fd];
+
+    unsigned poll_mask = 0;
+    // pre events
+    if (io->events & HV_READ) {
+        poll_mask |= POLLIN;
+    }
+    if (io->events & HV_WRITE) {
+        poll_mask |= POLLOUT;
+    }
+    // now events
+    if (events & HV_READ) {
+        poll_mask |= POLLIN;
+    }
+    if (events & HV_WRITE) {
+        poll_mask |= POLLOUT;
+    }
+
+    struct io_uring_sqe* sqe;
+    if (io->events != 0) {
+        // Cancel the existing poll request first
+        sqe = io_uring_get_sqe(&ctx->ring);
+        if (sqe == NULL) return -1;
+        io_uring_prep_poll_remove(sqe, (uint64_t)fd);
+        io_uring_sqe_set_data64(sqe, IO_URING_CANCEL_TAG);
+    } else {
+        ctx->nfds++;
+    }
+
+    // Add poll for the combined events
+    sqe = io_uring_get_sqe(&ctx->ring);
+    if (sqe == NULL) return -1;
+    io_uring_prep_poll_add(sqe, fd, poll_mask);
+    io_uring_sqe_set_data64(sqe, (uint64_t)fd);
+
+    io_uring_submit(&ctx->ring);
+    return 0;
+}
+
+int iowatcher_del_event(hloop_t* loop, int fd, int events) {
+    io_uring_ctx_t* ctx = (io_uring_ctx_t*)loop->iowatcher;
+    if (ctx == NULL) return 0;
+    hio_t* io = loop->ios.ptr[fd];
+
+    // Calculate remaining events
+    unsigned poll_mask = 0;
+    // pre events
+    if (io->events & HV_READ) {
+        poll_mask |= POLLIN;
+    }
+    if (io->events & HV_WRITE) {
+        poll_mask |= POLLOUT;
+    }
+    // now events
+    if (events & HV_READ) {
+        poll_mask &= ~POLLIN;
+    }
+    if (events & HV_WRITE) {
+        poll_mask &= ~POLLOUT;
+    }
+
+    // Cancel existing poll
+    struct io_uring_sqe* sqe = io_uring_get_sqe(&ctx->ring);
+    if (sqe == NULL) return -1;
+    io_uring_prep_poll_remove(sqe, (uint64_t)fd);
+    io_uring_sqe_set_data64(sqe, IO_URING_CANCEL_TAG);
+
+    if (poll_mask == 0) {
+        ctx->nfds--;
+    } else {
+        // Re-add with remaining events
+        sqe = io_uring_get_sqe(&ctx->ring);
+        if (sqe == NULL) return -1;
+        io_uring_prep_poll_add(sqe, fd, poll_mask);
+        io_uring_sqe_set_data64(sqe, (uint64_t)fd);
+    }
+
+    io_uring_submit(&ctx->ring);
+    return 0;
+}
+
+int iowatcher_poll_events(hloop_t* loop, int timeout) {
+    io_uring_ctx_t* ctx = (io_uring_ctx_t*)loop->iowatcher;
+    if (ctx == NULL) return 0;
+    if (ctx->nfds == 0) return 0;
+
+    struct __kernel_timespec ts;
+    struct __kernel_timespec* tp = NULL;
+    if (timeout != INFINITE) {
+        ts.tv_sec = timeout / 1000;
+        ts.tv_nsec = (timeout % 1000) * 1000000LL;
+        tp = &ts;
+    }
+
+    struct io_uring_cqe* cqe;
+    int ret;
+    if (tp) {
+        ret = io_uring_wait_cqe_timeout(&ctx->ring, &cqe, tp);
+    } else {
+        ret = io_uring_wait_cqe(&ctx->ring, &cqe);
+    }
+    if (ret < 0) {
+        if (ret == -ETIME || ret == -EINTR) {
+            return 0;
+        }
+        perror("io_uring_wait_cqe");
+        return ret;
+    }
+
+    int nevents = 0;
+    unsigned head;
+    unsigned ncqes = 0;
+    io_uring_for_each_cqe(&ctx->ring, head, cqe) {
+        ncqes++;
+        uint64_t data = io_uring_cqe_get_data64(cqe);
+        if (data == IO_URING_CANCEL_TAG) {
+            continue;
+        }
+
+        int fd = (int)data;
+        if (fd < 0 || fd >= loop->ios.maxsize) continue;
+        hio_t* io = loop->ios.ptr[fd];
+        if (io == NULL) continue;
+
+        if (cqe->res < 0) {
+            io->revents |= HV_READ;
+            EVENT_PENDING(io);
+            ++nevents;
+        } else {
+            int revents = cqe->res;
+            if (revents & (POLLIN | POLLHUP | POLLERR)) {
+                io->revents |= HV_READ;
+            }
+            if (revents & (POLLOUT | POLLHUP | POLLERR)) {
+                io->revents |= HV_WRITE;
+            }
+            if (io->revents) {
+                EVENT_PENDING(io);
+                ++nevents;
+            }
+        }
+
+        // io_uring POLL_ADD is one-shot, re-arm for the same events
+        unsigned remask = 0;
+        if (io->events & HV_READ) remask |= POLLIN;
+        if (io->events & HV_WRITE) remask |= POLLOUT;
+        if (remask) {
+            struct io_uring_sqe* sqe = io_uring_get_sqe(&ctx->ring);
+            if (sqe) {
+                io_uring_prep_poll_add(sqe, fd, remask);
+                io_uring_sqe_set_data64(sqe, (uint64_t)fd);
+            }
+        }
+    }
+
+    io_uring_cq_advance(&ctx->ring, ncqes);
+
+    if (nevents > 0) {
+        io_uring_submit(&ctx->ring);
+    }","duplicate_id_conflict":false,"event_at":"2026-03-11T03:43:17+00:00","event_key":"inline_comment:2915677850","event_type":"inline_comment","html_url":null,"id":"2915677850","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"6113c3183dcee578d13c770437ec4979b3ff0304","original_line":null,"original_position":205,"original_start_line":null,"path":"event/io_uring.c","position":228,"pull_request_review_id":"3926689789","pull_request_url":"https://api.github.com/repos/ithewei/libhv/pulls/813","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/ithewei/libhv/pull/813","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-03-11T03:43:18Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"The `-luring` linker flag is added whenever `WITH_IO_URING=yes`, regardless of platform. Since liburing is Linux-specific, enabling this flag on non-Linux targets will break linking; consider additionally guarding this block with `ifeq ($(OS), Linux)` (or equivalent) so the option is only effective on Linux.
```suggestion

ifeq ($(OS), Linux)
ifeq ($(WITH_IO_URING), yes)
	LDFLAGS += -luring
endif
endif
