[{"author_association":null,"body":"`extractFilenamesFromPatch` only captures the `b/<path>` side of `diff --git a/<old> b/<new>` headers. For renames/copies this can miss the original filename (e.g., renaming `package.json` -> `package.json.bak` would not be flagged), which undermines manifest-file protection. Parse *both* the `a/<path>` and `b/<path>` values (ignoring `/dev/null`) and include both basenames in the returned set; add a unit test that covers a rename header.","body_updated_after_merge":false,"commit_id":"dbcc31ec83c6ddb10e0e3053978f751248f546cf","created_at":"2026-03-07T15:09:28Z","diff_hunk":"@@ -0,0 +1,45 @@
+// @ts-check
+
+/**
+ * Extracts the unique set of file basenames (filename without directory path) changed in a git patch.
+ * Parses "diff --git a/<path> b/<path>" headers to determine which files were modified.
+ *
+ * @param {string} patchContent - The git patch content
+ * @returns {string[]} Deduplicated list of file basenames changed in the patch
+ */
+function extractFilenamesFromPatch(patchContent) {
+  if (!patchContent || !patchContent.trim()) {
+    return [];
+  }
+  const fileSet = new Set();
+  const matches = patchContent.matchAll(/^diff --git a\/.+ b\/(.+)$/gm);
+  for (const match of matches) {
+    const filePath = match[1];
+    const parts = filePath.split("/");
+    const basename = parts[parts.length - 1];","duplicate_id_conflict":false,"event_at":"2026-03-07T15:09:28+00:00","event_key":"inline_comment:2899868299","event_type":"inline_comment","html_url":null,"id":"2899868299","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"dbcc31ec83c6ddb10e0e3053978f751248f546cf","original_line":null,"original_position":19,"original_start_line":null,"path":"actions/setup/js/manifest_file_helpers.cjs","position":1,"pull_request_review_id":"3908920332","pull_request_url":"https://api.github.com/repos/github/gh-aw/pulls/19958","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/github/gh-aw/pull/19958","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-03-07T15:09:29Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"The manifest-protection remediation snippet is hard-coded to `safe-outputs.create-pull-request`, even when the blocked operation is `push_to_pull_request_branch` (or multiple operations are blocked). Generate the YAML snippet based on the blocked safe-output type(s) so the suggested config matches what actually failed (e.g., `push-to-pull-request-branch:` when that handler is blocked, or include both when mixed).","body_updated_after_merge":false,"commit_id":"1b95060881f490c7d7a705f609c476d37ef69dd9","created_at":"2026-03-07T15:09:29Z","diff_hunk":"@@ -312,59 +314,93 @@ function buildCodePushFailureContext(codePushFailureErrors, pullRequest = null)
