+        {
+            using (FileStream fs = File.Open(zipArchivePath, FileMode.Create, FileAccess.ReadWrite))","duplicate_id_conflict":false,"event_at":"2026-01-04T00:36:43+00:00","event_key":"inline_comment:2659234205","event_type":"inline_comment","html_url":null,"id":"2659234205","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"ba3bdd7ae494ce2ee39393f8f4637fb508b9bba8","original_line":null,"original_position":18,"original_start_line":null,"path":"src/libraries/System.IO.Compression/tests/ZipArchive/zip_LargeFiles.cs","position":35,"pull_request_review_id":"3624611675","pull_request_url":"https://api.github.com/repos/dotnet/runtime/pulls/122837","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/dotnet/runtime/pull/122837","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-01-04T00:36:44Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"These two consecutive await using statements both have parentheses and are trying to share the same code block starting at line 173, which is not valid C# syntax. The first using statement should be a using declaration (without parentheses) to properly nest the disposables. Change line 171 to use a using declaration: `await using FileStream fs = File.OpenRead(zipArchivePath);` (note the semicolon instead of the opening brace being on the next line).
