+    <a
       ref={ref}
       href={href}
-      className={className || CS.link}
+      className={`${S.LinkRoot} ${className || CS.link}`}","duplicate_id_conflict":false,"event_at":"2026-01-26T15:16:54+00:00","event_key":"inline_comment:2728017502","event_type":"inline_comment","html_url":null,"id":"2728017502","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"30786d48e687be97fee8c87a2828ad15d12375aa","original_line":null,"original_position":17,"original_start_line":null,"path":"frontend/src/metabase/common/components/ExternalLink/ExternalLink.tsx","position":17,"pull_request_review_id":"3706519302","pull_request_url":"https://api.github.com/repos/metabase/metabase/pulls/66851","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/metabase/metabase/pull/66851","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"after_merge","updated_at":"2026-01-26T15:16:54Z","url":null,"user":"metabase-bot[bot]","user_id":null,"user_type":"Bot"}]

