+h1, h2, h3, h4, h5, h6 {
+    text-wrap: balance; // Creates more visually balanced multi-line headings
+}
+
+p {
+    text-wrap: pretty; // Avoids orphans (single words on last line) for better readability
+}
+
+// Hanging punctuation for blockquotes and pull quotes
+// Pushes punctuation into the margin for optically aligned text edges
+// Note: Currently only supported in Safari, graceful degradation in other browsers
+blockquote {
+    hanging-punctuation: first last; // Hang opening and closing punctuation
+}
+
+// Enhanced text selection styles for better readability
+::selection {
+    background-color: rgba(51, 122, 183, 0.3); // Primary blue with transparency
+    color: inherit; // Preserve text color for better contrast
+}
+
+// Dark mode selection adjustment
+@media (prefers-color-scheme: dark) {
+    ::selection {
+        background-color: rgba(51, 122, 183, 0.4); // Slightly more opaque for dark mode
+    }
+}
+
+// Word spacing optimization for justified text (if used)
+// Slightly tighter word spacing improves readability for long-form content
+article, .post-content, .content {
+    word-spacing: -0.02em; // Subtle tightening for better text flow
+}
+
+// Improved first paragraph styling (lead paragraph)
+// The first paragraph after a heading often benefits from slightly larger text
+article > p:first-of-type,
+.post-content > p:first-of-type {
+    font-size: 1.125em; // Slightly larger for engagement
+    line-height: 1.75; // Slightly increased line height for the larger text
+}
+
+// Drop cap for engaging article starts (applied via .drop-cap class)
+// Use sparingly - best for feature articles or blog posts
+// Note: Screen readers handle ::first-letter well in modern browsers;
+// the first letter remains part of the word in the accessibility tree
+.drop-cap::first-letter {
+    float: left;
+    font-size: 3.5em;
+    line-height: 0.8;
+    padding-right: 0.1em;
+    font-weight: 700;
+    color: var(--bs-primary);
+    margin-top: 0.1em;
