[{"author_association":null,"body":"@copilot I don't think this is needed. If you add a `guessInfo` to TheNighthold implementation, this should be picked in secret-created-in-game-parser, then used by this.secretConfig.getValidSecrets

Or do you think this won't work?","body_updated_after_merge":false,"commit_id":"fd0eb612460912bba566745f879c5ade077dd790","created_at":"2026-01-23T14:29:20Z","diff_hunk":"@@ -0,0 +1,29 @@
+// The Nighthold: Cast a random secret from your class
+// According to game behavior, it casts from the full pool of all Paladin secrets,
+// not constrained by the current game mode (e.g., arena rotation)
+import { CardClass, CardIds, CardType, GameTag, hasMechanic } from '@firestone-hs/reference-data';
+import { GameState } from '@firestone/game-state';
+import { CardsFacadeService, HighlightSide } from '@firestone/shared/framework/core';
