[{"author_association":null,"body":"In this effect, `getAvailableBackendWorkspaces()` can resolve and call `setEnabledWorkspaces()` before `setCurrentPlatform()` runs. Since `setEnabledWorkspaces()` computes availability using the current `currentPlatform` in the store (defaulting to "windows"), it can incorrectly reset `activeWorkspace`/`activeView` to "log" on non-Windows platforms. Consider determining + setting the platform first, then loading backend workspaces (or passing the mapped platform into `setEnabledWorkspaces` so the availability check uses the right platform).","body_updated_after_merge":false,"commit_id":"d59f6af80af3a61ca2d2db5d3d65cd8042427869","created_at":"2026-03-31T13:10:23Z","diff_hunk":"@@ -782,18 +791,39 @@ export function Toolbar() {
