+import type { SecretClient } from '@azure/keyvault-secrets';
+import { injectable } from 'inversify';
+import type { ISecretProvider } from '../../domain/ports/ISecretProvider.js';
+
+/**
+ * Azure Key Vault secret provider implementation.
+ * Implements the same interface as AWS SSM provider for consistency.
+ */
+@injectable()
+export class AzureKeyVaultSecretProvider implements ISecretProvider {
+  private client: SecretClient;
+
+  constructor(client: SecretClient) {
+    this.client = client;
+  }
+
+  async getSecret(name: string): Promise<string | undefined> {
+    try {
+      const secretName = this.normalizeSecretName(name);
+      const secret = await this.client.getSecret(secretName);
+      return secret.value;
+    } catch (error) {
+      if (
+        typeof error === 'object' &&
+        error !== null &&
+        'statusCode' in error &&
+        error.statusCode === 404
+      ) {
+        return undefined;
+      }
+      const errorMessage =
+        error instanceof Error ? error.message : String(error);
+      throw new Error(`Failed to get secret ${name}: ${errorMessage}`);
+    }
+  }
+
+  async setSecret(name: string, value: string): Promise<void> {
+    const secretName = this.normalizeSecretName(name);
+    await this.client.setSecret(secretName, value);
+  }
+
+  /**
+   * Normalize secret name to comply with Azure Key Vault naming requirements.
+   * Azure Key Vault secret names must:
+   * - Be 1-127 characters long
+   * - Contain only alphanumeric characters and hyphens
+   * - Start with a letter
+   */
+  private normalizeSecretName(name: string): string {
+    // Remove leading slashes
+    let normalized = name.replace(/^\/+/, '');
+
+    // Replace slashes and underscores with hyphens
+    normalized = normalized.replace(/[/_]/g, '-');
+
+    // Remove invalid characters
+    normalized = normalized.replace(/[^a-zA-Z0-9-]/g, '');
+
+    // Remove consecutive hyphens
+    normalized = normalized.replace(/-+/g, '-');
+
+    // Remove leading/trailing hyphens
+    normalized = normalized.replace(/^-+|-+$/g, '');
+
+    // Ensure starts with a letter
+    if (normalized.length > 0 && !/^[a-zA-Z]/.test(normalized)) {
+      normalized = `secret-${normalized}`;
+    }
+
+    // Truncate to 127 characters
+    if (normalized.length > 127) {
+      normalized = normalized.substring(0, 127);
+    }","duplicate_id_conflict":false,"event_at":"2026-03-22T18:04:12+00:00","event_key":"inline_comment:2971855144","event_type":"inline_comment","html_url":null,"id":"2971855144","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"51698017e43c9e3de3e9e90db1252eff2e887af9","original_line":null,"original_position":73,"original_start_line":null,"path":"src/envilder/infrastructure/azure/AzureKeyVaultSecretProvider.ts","position":1,"pull_request_review_id":"3988395127","pull_request_url":"https://api.github.com/repos/macalbert/envilder/pulls/90","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/macalbert/envilder/pull/90","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-03-22T18:04:13Z","url":null,"user":"devin-ai-integration[bot]","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"**Addressed.** Five Azure provider tests exist in `tests/apps/cli/Startup.test.ts`:

