+import type { SecretClient } from '@azure/keyvault-secrets';
+import { injectable } from 'inversify';
+import { SecretOperationError } from '../../domain/errors/DomainErrors.js';
+import type { ISecretProvider } from '../../domain/ports/ISecretProvider.js';
+
+@injectable()
+export class AzureKeyVaultSecretProvider implements ISecretProvider {
+  private client: SecretClient;
+
+  constructor(client: SecretClient) {
+    this.client = client;
+  }
+
+  async getSecret(name: string): Promise<string | undefined> {
+    try {
+      const secretName = this.normalizeSecretName(name);
+      const secret = await this.client.getSecret(secretName);
+      return secret?.value ?? undefined;
+    } catch (error) {
+      if (
+        typeof error === 'object' &&
+        error !== null &&
+        'statusCode' in error &&
+        error.statusCode === 404
+      ) {
+        return undefined;
+      }
+      const errorMessage =
+        error instanceof Error ? error.message : String(error);
+      throw new SecretOperationError(
+        `Failed to get secret ${name}: ${errorMessage}`,
+      );
+    }
+  }
+
+  async setSecret(name: string, value: string): Promise<void> {
+    try {
+      const secretName = this.normalizeSecretName(name);
+      await this.client.setSecret(secretName, value);
+    } catch (error) {
+      const errorMessage =
+        error instanceof Error ? error.message : String(error);
+      throw new SecretOperationError(
+        `Failed to set secret ${name}: ${errorMessage}`,
+      );
+    }
+  }
+
+  // Azure Key Vault secret names: 1-127 chars, alphanumeric + hyphens, start with letter
+  private normalizeSecretName(name: string): string {
+    // Remove leading slashes
+    let normalized = name.replace(/^\/+/, '');
+
+    // Replace slashes and underscores with hyphens
+    normalized = normalized.replace(/[/_]/g, '-');
+
+    // Remove invalid characters
+    normalized = normalized.replace(/[^a-zA-Z0-9-]/g, '');
+
+    // Remove consecutive hyphens
+    normalized = normalized.replace(/-+/g, '-');
+
+    // Remove leading/trailing hyphens
+    normalized = normalized.replace(/^-+|-+$/g, '');
+
+    // Ensure starts with a letter
+    if (normalized.length > 0 && !/^[a-zA-Z]/.test(normalized)) {
+      normalized = `secret-${normalized}`;
+    }
+
+    // Truncate to 127 characters and strip any trailing hyphen
+    if (normalized.length > 127) {
+      normalized = normalized.substring(0, 127);
+      normalized = normalized.replace(/-+$/, '');
+    }
+
+    // Default name if empty
+    if (normalized.length === 0) {
+      normalized = 'secret';
+    }
+
+    return normalized;
+  }","duplicate_id_conflict":false,"event_at":"2026-03-25T07:28:44+00:00","event_key":"inline_comment:2986321267","event_type":"inline_comment","html_url":null,"id":"2986321267","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"66693cffd38d03e376ad3bb21d4a0cd52eb8ba25","original_line":null,"original_position":83,"original_start_line":null,"path":"src/envilder/infrastructure/azure/AzureKeyVaultSecretProvider.ts","position":117,"pull_request_review_id":"4004554897","pull_request_url":"https://api.github.com/repos/macalbert/envilder/pulls/90","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/macalbert/envilder/pull/90","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-03-25T10:37:24Z","url":null,"user":"devin-ai-integration[bot]","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"<!-- devin-review-comment {"id": "BUG_pr-review-job-6f85e94518ba44bbbdef28611098c676_0001", "file_path": "vite.config.ts", "start_line": 8, "end_line": 8, "side": "RIGHT"} -->

🔴 **E2E and integration tests included in default `pnpm test` / `pnpm test:ci` without Docker guard**

The `e2e/**` exclusion was removed from `vite.config.ts`, and the `describe.runIf(process.env.CI || process.env.INTEGRATION)` guard was simultaneously removed from `tests/envilder/infrastructure/aws/AwsSsmSecretProvider.test.ts`. This means `pnpm test` and `pnpm test:ci` now unconditionally run e2e tests (`e2e/cli.test.ts`, `e2e/gha.test.ts`) and integration tests that start Docker containers (LocalStack, Lowkey Vault), build and globally install packages, and require live AWS credentials. Any developer running `pnpm test` without Docker will see failures from container startup timeouts. The CI workflow step labeled "Run unit-test" (`pnpm test:ci`) now also runs the full e2e suite, significantly increasing CI time and coupling unit-test feedback to Docker container availability.

<details>
<summary>Prompt for agents</summary>

```
Restore the e2e test exclusion in vite.config.ts by changing line 8 from:
  exclude: ['node_modules/**'],
to:
  exclude: ['e2e/**', 'node_modules/**'],

Also restore the describe.runIf guard in tests/envilder/infrastructure/aws/AwsSsmSecretProvider.test.ts around the 'integration with LocalStack' describe block. It should be:
  describe.runIf(process.env.CI || process.env.INTEGRATION)('AwsSsmSecretProvider (integration with LocalStack)', () => {

If you want e2e tests in CI, add a separate CI step or a separate test script (e.g. test:e2e) rather than including them in the default pnpm test run.
```

</details>

