+      await this.client.setSecret(secretName, value);
+    } catch (error) {
+      const errorMessage =
+        error instanceof Error ? error.message : String(error);
+      throw new SecretOperationError(
+        `Failed to set secret ${name}: ${errorMessage}`,
+      );
+    }
+  }
+
+  // Azure Key Vault secret names: 1-127 chars, alphanumeric + hyphens, start with letter
+  private normalizeSecretName(name: string): string {
+    // Remove leading slashes
+    let normalized = name.replace(/^\/+/, '');
+
+    // Replace slashes and underscores with hyphens
+    normalized = normalized.replace(/[/_]/g, '-');
+
+    // Remove invalid characters
+    normalized = normalized.replace(/[^a-zA-Z0-9-]/g, '');
+
+    // Remove consecutive hyphens
+    normalized = normalized.replace(/-+/g, '-');
+
+    // Remove leading/trailing hyphens
+    normalized = normalized.replace(/^-+|-+$/g, '');
+
+    // Ensure starts with a letter
+    if (normalized.length > 0 && !/^[a-zA-Z]/.test(normalized)) {
+      normalized = `secret-${normalized}`;
+    }
+
+    // Truncate to 127 characters and strip any trailing hyphen
+    if (normalized.length > 127) {
+      normalized = normalized.substring(0, 127);
+      normalized = normalized.replace(/-+$/, '');
+    }
+
+    // Default name if empty
+    if (normalized.length === 0) {
+      normalized = 'secret';
+    }
+
+    return normalized;
+  }","duplicate_id_conflict":false,"event_at":"2026-03-26T00:47:16+00:00","event_key":"inline_comment:2991859729","event_type":"inline_comment","html_url":null,"id":"2991859729","in_reply_to_id":"2986321267","is_feedback_candidate":true,"is_human":true,"line":null,"original_commit_id":"66693cffd38d03e376ad3bb21d4a0cd52eb8ba25","original_line":null,"original_position":83,"original_start_line":null,"path":"src/envilder/infrastructure/azure/AzureKeyVaultSecretProvider.ts","position":117,"pull_request_review_id":"4010762709","pull_request_url":"https://api.github.com/repos/macalbert/envilder/pulls/90","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/macalbert/envilder/pull/90","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-03-26T00:47:16Z","url":null,"user":"macalbert","user_id":null,"user_type":"User"},{"author_association":null,"body":"**Intentional design.** The e2e tests use TestContainers which automatically skip when Docker is unavailable (the container startup throws and the `beforeAll` failure skips the entire describe block). This is the established pattern in this project.

