[{"author_association":null,"body":""stopped after"` is a very broad substring and could accidentally classify unrelated errors as retryable (leading to unnecessary retries). Consider narrowing this match to redirect-specific wording (e.g., matching `"stopped after 10 redirects"` or a regexp like `stopped after \d+ redirects`) so only the intended redirect-limit failures trigger retries.","body_updated_after_merge":false,"commit_id":"4e24b1b07e9a8192536a7d2e2a84cce813e4dbb5","created_at":"2026-03-05T20:07:25Z","diff_hunk":"@@ -31,6 +31,7 @@ func IsRetryable(err error) bool {
 		"i/o timeout", "TLS handshake timeout",
 		"unexpected EOF", "no such host",
 		"context deadline exceeded",
+		"stopped after",
 	}","duplicate_id_conflict":false,"event_at":"2026-03-05T20:07:25+00:00","event_key":"inline_comment:2892014750","event_type":"inline_comment","html_url":null,"id":"2892014750","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"4e24b1b07e9a8192536a7d2e2a84cce813e4dbb5","original_line":null,"original_position":5,"original_start_line":null,"path":"pkg/client/netretry/netretry.go","position":1,"pull_request_review_id":"3899340707","pull_request_url":"https://api.github.com/repos/devantler-tech/ksail/pulls/2821","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/devantler-tech/ksail/pull/2821","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-03-05T20:07:26Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"When retries are exhausted (or the error is deemed non-retryable), the function returns the raw last error, which loses useful context that retries occurred and how many attempts were made. Consider wrapping the final error with attempt count (and optionally whether it was non-retryable), e.g. “push failed after 3 attempts: …”, to make troubleshooting CI/network flakiness easier without changing behavior.","body_updated_after_merge":false,"commit_id":"91146be127ff638ea82a04672ba561424bbe9f6e","created_at":"2026-03-05T20:07:25Z","diff_hunk":"@@ -80,8 +92,47 @@ func pushImage(
 		remoteOpts = append(remoteOpts, remote.WithAuth(auth))
 	}

+	return pushWithRetry(ctx, ref, img, remoteOpts, remote.Write)
+}
+
+// pushWithRetry retries the push operation on transient errors with exponential backoff.
+func pushWithRetry(
+	ctx context.Context,
+	ref name.Reference,
+	img v1.Image,
+	remoteOpts []remote.Option,
+	push pushFn,
+) error {
+	var lastErr error
+
+	for attempt := 1; attempt <= pushMaxAttempts; attempt++ {
+		err := push(ref, img, remoteOpts...)
+		if err == nil {
+			return nil
+		}
+
+		lastErr = err
+
+		if !netretry.IsRetryable(lastErr) || attempt == pushMaxAttempts {
+			break
+		}
+
+		delay := netretry.ExponentialDelay(attempt, pushRetryBaseWait, pushRetryMaxWait)","duplicate_id_conflict":false,"event_at":"2026-03-05T20:07:25+00:00","event_key":"inline_comment:2892014787","event_type":"inline_comment","html_url":null,"id":"2892014787","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"4e24b1b07e9a8192536a7d2e2a84cce813e4dbb5","original_line":null,"original_position":62,"original_start_line":null,"path":"pkg/client/oci/builder_impl.go","position":64,"pull_request_review_id":"3899340707","pull_request_url":"https://api.github.com/repos/devantler-tech/ksail/pulls/2821","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/devantler-tech/ksail/pull/2821","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-03-05T20:07:26Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"mockPushFn panics if called with an empty errs slice (errs[len(errs)-1]). Adding a small guard (e.g., defaulting to nil or a sentinel error when len(errs)==0) would make the helper safer for future test cases and reduce the chance of accidental panics obscuring failures.
```suggestion

		if len(errs) == 0 {
			return nil
		}
```","body_updated_after_merge":false,"commit_id":"91146be127ff638ea82a04672ba561424bbe9f6e","created_at":"2026-03-05T20:07:25Z","diff_hunk":"@@ -98,3 +118,134 @@ func TestBuild(t *testing.T) {
 	// Note: We cannot test successful builds without a running registry.
 	// Integration tests should cover the full push workflow.
 }
+
+// mockPushFn creates a mock push function that returns errors from the given
+// list per attempt, tracking call count via the atomic counter.
+func mockPushFn(
+	callCount *atomic.Int32,
+	errs []error,
+) oci.PushFn {
+	return func(_ name.Reference, _ v1.Image, _ ...remote.Option) error {
+		idx := int(callCount.Add(1)) - 1
+		if idx < len(errs) {
+			return errs[idx]
+		}
+","duplicate_id_conflict":false,"event_at":"2026-03-05T20:07:25+00:00","event_key":"inline_comment:2892014815","event_type":"inline_comment","html_url":null,"id":"2892014815","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"4e24b1b07e9a8192536a7d2e2a84cce813e4dbb5","original_line":null,"original_position":52,"original_start_line":null,"path":"pkg/client/oci/builder_impl_test.go","position":53,"pull_request_review_id":"3899340707","pull_request_url":"https://api.github.com/repos/devantler-tech/ksail/pulls/2821","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/devantler-tech/ksail/pull/2821","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-03-05T20:07:26Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"}]

