+            using (var _ = new FileStream(testFile, FileMode.Open, FileAccess.ReadWrite, FileShare.None))","duplicate_id_conflict":false,"event_at":"2026-01-13T08:49:32+00:00","event_key":"inline_comment:2685454895","event_type":"inline_comment","html_url":null,"id":"2685454895","in_reply_to_id":"2685426355","is_feedback_candidate":true,"is_human":true,"line":null,"original_commit_id":"8a4f36c2678d4e89afda38f4799537c4fead85d7","original_line":null,"original_position":76,"original_start_line":null,"path":"MobiFlightUnitTests/SimConnectMSFS/WasmModuleUpdaterTests.cs","position":1,"pull_request_review_id":"3654614915","pull_request_url":"https://api.github.com/repos/MobiFlight/MobiFlight-Connector/pulls/2618","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/mobiflight/mobiflight-connector/pull/2618","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-01-13T08:49:33Z","url":null,"user":"DocMoebiuz","user_id":null,"user_type":"User"},{"author_association":null,"body":"@copilot apply changes based on [this feedback](https://github.com/MobiFlight/MobiFlight-Connector/pull/2618#discussion_r2685426339)","body_updated_after_merge":false,"commit_id":"8a4f36c2678d4e89afda38f4799537c4fead85d7","created_at":"2026-01-13T08:50:03Z","diff_hunk":"@@ -0,0 +1,122 @@
