[{"author_association":null,"body":"`targetBufferSize` is recalculated every frame, but the buffer management only ever removes at most 1 frame per render tick. If `detectedFPS` increases after playback has started, the `buffer.length >= targetBufferSize` check will suddenly fail and the canvas will stop updating until the buffer grows to the new target (visible freeze). If `detectedFPS` decreases, the buffer will stay larger than the new target (delay remains too long) because it never shrinks toward the lower target. Consider either (a) locking the buffer size once output begins, or (b) actively trimming/expanding toward the target (e.g., drop extra frames when target decreases; when increasing, continue drawing but adjust shift cadence) so the delay converges without freezes.","body_updated_after_merge":false,"commit_id":"5222081202c82bf15d8bad54b235e327b23ec497","created_at":"2026-03-12T14:30:50Z","diff_hunk":"@@ -386,10 +381,12 @@ function startDelayedPlayback() {
       // Add the frame to our buffer
       buffer.push(bitmap);

-      // If buffer is full, start showing the delayed frames
-      if (buffer.length >= bufferSize) {
-        shouldOutput = true;
+      // Recalculate target buffer size each frame so changes in detectedFPS
+      // (updated by detectFPS() during the first ~2 s) are reflected correctly
+      const targetBufferSize = delaySeconds.value * detectedFPS.value;

+      // If buffer is full, start showing the delayed frames
+      if (buffer.length >= targetBufferSize) {
         // Get the oldest frame","duplicate_id_conflict":false,"event_at":"2026-03-12T14:30:50+00:00","event_key":"inline_comment:2925074333","event_type":"inline_comment","html_url":null,"id":"2925074333","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"5222081202c82bf15d8bad54b235e327b23ec497","original_line":null,"original_position":28,"original_start_line":null,"path":"entrypoints/match.content/InstantReplay.vue","position":1,"pull_request_review_id":"3937114997","pull_request_url":"https://api.github.com/repos/creazy231/tools-for-autodarts/pulls/208","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/creazy231/tools-for-autodarts/pull/208","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-03-12T14:30:50Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"This z-index change conflicts with the PR description: `InstantReplay.vue` uses `z-[190]`, so changing Animations to `z-[150]` will place animations behind the replay overlay when both are visible. If animations are intended to remain above the replay while still below modal overlays (`z-[200]`), pick a z-index between 191–199 (or update the PR description if the new stacking order is intended).","body_updated_after_merge":false,"commit_id":"5222081202c82bf15d8bad54b235e327b23ec497","created_at":"2026-03-12T14:30:50Z","diff_hunk":"@@ -2,7 +2,7 @@
