+#[test]
+fn test_lifetime_subscription_weight_accumulation() {
+    new_test_ext().execute_with(|| {
+        Timestamp::set_timestamp(1_000_000);
+
+        // Create lifetime subscription with 500_000 μTPS (0.5 TPS)
