 let accessToken: string | null = null;
 let accessTokenExpiry = 0;

+// Card instance cache for streaming updates
+const cardInstances = new Map<string, CardInstance>();
+
+// Cache cleanup interval (1 hour)
+const CARD_CACHE_TTL = 60 * 60 * 1000; // 1 hour
+
+// Clean up old card instances from cache
+function cleanupCardCache() {
+  const now = Date.now();
+  for (const [cardBizId, instance] of cardInstances.entries()) {
+    if (now - instance.lastUpdated > CARD_CACHE_TTL) {
+      cardInstances.delete(cardBizId);
+    }
+  }
+}
+
+// Run cleanup periodically (every 30 minutes)
+setInterval(cleanupCardCache, 30 * 60 * 1000);","duplicate_id_conflict":false,"event_at":"2026-01-29T07:58:54+00:00","event_key":"inline_comment:2740402817","event_type":"inline_comment","html_url":null,"id":"2740402817","in_reply_to_id":"2740098423","is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"11792715475e8015ccaa821cca6c467d9af4aa57","original_line":null,"original_position":32,"original_start_line":null,"path":"src/channel.ts","position":1,"pull_request_review_id":"3721218821","pull_request_url":"https://api.github.com/repos/soimy/openclaw-channel-dingtalk/pulls/7","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/soimy/openclaw-channel-dingtalk/pull/7","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-01-29T07:58:54Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"Fixed in 2468b3d. Wrapped both `sendInteractiveCard` and `updateInteractiveCard` axios calls in `retryWithBackoff()` with maxRetries=3 for consistency with other API functions.","body_updated_after_merge":false,"commit_id":"11792715475e8015ccaa821cca6c467d9af4aa57","created_at":"2026-01-29T07:58:57Z","diff_hunk":"@@ -283,6 +308,169 @@ async function sendBySession(
