+  } else {
+    payload.singleChatReceiver = JSON.stringify({ userId: conversationId });
+  }
+  
+  const result = await axios({
+    url: 'https://api.dingtalk.com/v1.0/im/v1.0/robot/interactiveCards/send',
+    method: 'POST',
+    data: payload,
+    headers: { 'x-acs-dingtalk-access-token': token, 'Content-Type': 'application/json' },
+  });
+  
+  // Cache card instance for future updates
+  cardInstances.set(cardBizId, {
+    cardBizId,
+    conversationId,
+    createdAt: Date.now(),
+    lastUpdated: Date.now(),
+  });
+  
+  return { cardBizId, response: result.data };
+}
+
+// Update existing interactive card (for streaming updates)
+async function updateInteractiveCard(
+  config: DingTalkConfig,
+  cardBizId: string,
+  text: string,
+  options: SendMessageOptions = {}
+): Promise<any> {
+  const token = await getAccessToken(config, options.log);
+  
+  // Extract title from text
+  const { title } = detectMarkdownAndExtractTitle(text, options, 'Clawdbot 消息');
+  
+  // Build updated card data
+  const cardData: InteractiveCardData = {
+    config: {
+      autoLayout: true,
+      enableForward: true,
+    },
+    header: {
+      title: {
+        type: 'text',
+        text: title,
+      },
+    },
+    contents: [
+      {
+        type: 'text',
+        text: text,
+      },
+    ],
+  };
+  
+  // Build update request
+  const payload: InteractiveCardUpdateRequest = {
+    cardBizId,
+    cardData: JSON.stringify(cardData),
+    updateOptions: {
+      updateCardDataByKey: false,
+    },
+  };
+  
+  const result = await axios({
+    url: 'https://api.dingtalk.com/v1.0/im/robots/interactiveCards',
+    method: 'PUT',
+    data: payload,
+    headers: { 'x-acs-dingtalk-access-token': token, 'Content-Type': 'application/json' },
+  });
+  
+  // Update cache
+  const instance = cardInstances.get(cardBizId);
+  if (instance) {
+    instance.lastUpdated = Date.now();
+  }
+  
+  return result.data;
+}","duplicate_id_conflict":false,"event_at":"2026-01-29T07:59:01+00:00","event_key":"inline_comment:2740403156","event_type":"inline_comment","html_url":null,"id":"2740403156","in_reply_to_id":"2740098444","is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"11792715475e8015ccaa821cca6c467d9af4aa57","original_line":null,"original_position":182,"original_start_line":null,"path":"src/channel.ts","position":1,"pull_request_review_id":"3721219166","pull_request_url":"https://api.github.com/repos/soimy/openclaw-channel-dingtalk/pulls/7","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/soimy/openclaw-channel-dingtalk/pull/7","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-01-29T07:59:01Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"Fixed in 2468b3d. Added validation at the start of `sendInteractiveCard()` to ensure robotCode or clientId is configured, throwing an error if neither is set.","body_updated_after_merge":false,"commit_id":"0bf5cfc77195000af0131fb408679cfab64d2c16","created_at":"2026-01-29T07:59:04Z","diff_hunk":"@@ -283,6 +308,169 @@ async function sendBySession(
