[{"author_association":null,"body":"The assign_to_user schema is missing the "repo" field that is supported by the runtime handler. The unassign_from_user tool (lines 564-595) includes a "repo" field, and the assign_to_user runtime handler (actions/setup/js/assign_to_user.cjs:61) supports cross-repository operations using resolveAndValidateRepo. The schema should include a "repo" property with the same structure as unassign_from_user for consistency and to enable cross-repository assignment workflows.","body_updated_after_merge":false,"commit_id":"c575e3aa05367adf1b622dd04bf5420cb60e675f","created_at":"2026-02-16T16:12:56Z","diff_hunk":"@@ -561,6 +561,38 @@
