[Show more details](https://github.com/OpenRakis/Spice86/security/code-scanning/2330)","body_updated_after_merge":true,"commit_id":"2e552a9f289fdaab17fc319c3bb8014efc6008af","created_at":"2026-01-08T23:39:57Z","diff_hunk":"@@ -0,0 +1,187 @@
+namespace Spice86.Tests.Emulator.Devices.Sound;
+
+using FluentAssertions;
+using Spice86.Libs.Sound.Common;
+using Xunit;
+using Xunit.Abstractions;
+using global::Bufdio.Spice86;
+
+/// <summary>
+/// Diagnostic tests for the Speex resampler with OPL-specific rates.
+/// Tests the exact scenario: 49716 Hz (OPL) → 48000 Hz (Mixer)
+/// 
+/// NOTE: These tests use normalized float input ([-1.0, 1.0]) for the sine wave generator,
+/// but in the actual Spice86 pipeline, AudioFrame uses int16-ranged floats matching DOSBox.
+/// The Speex resampler preserves the input scale regardless of whether it's normalized
+/// or int16-ranged.
+/// </summary>
+public class ResamplingDiagnosticTests {
+    private readonly ITestOutputHelper _output;
+    private const int OplSampleRateHz = 49716;
+    private const int MixerSampleRateHz = 48000;
+    private const uint SpeexChannels = 2; // stereo
+    private const int SpeexQuality = 5;
+    
+    public ResamplingDiagnosticTests(ITestOutputHelper output) {
+        _output = output;
+    }
+    
+    [Fact]
+    public void Speex_Resampler_OPL_To_Mixer_Rates_Works() {
+        // Arrange: Create Speex resampler with OPL → Mixer rates
+        using SpeexResamplerCSharp resampler = new(
+            SpeexChannels,
+            (uint)OplSampleRateHz,
+            (uint)MixerSampleRateHz,
+            SpeexQuality);
+        
+        _output.WriteLine($"Resampler configured: {OplSampleRateHz} Hz → {MixerSampleRateHz} Hz");
+        
+        // Act: Generate a 440Hz sine wave at OPL rate
+        int inputFrames = 4972; // ~100ms at 49716 Hz
+        float[] inputBuffer = GenerateSineWave(440.0f, OplSampleRateHz, inputFrames);
+        
+        // Calculate expected output frames
+        resampler.GetRatio(out uint ratioNum, out uint ratioDen);
+        int expectedOutputFrames = (int)Math.Ceiling((double)inputFrames * ratioDen / ratioNum);
+        _output.WriteLine($"Input: {inputFrames} frames, Expected output: ~{expectedOutputFrames} frames");
+        _output.WriteLine($"Ratio: {ratioNum}/{ratioDen}");
+        
+        float[] outputBuffer = new float[expectedOutputFrames * 2 + 100]; // Extra space
+        
+        // Resample
+        resampler.ProcessInterleavedFloat(
+            inputBuffer.AsSpan(),
+            outputBuffer.AsSpan(),
+            out uint inFramesConsumed,
+            out uint outFramesGenerated);
+        
+        _output.WriteLine($"Consumed: {inFramesConsumed} frames, Generated: {outFramesGenerated} frames");
+        
+        // Assert: Should generate frames
+        // Note: Speex resampler outputs in the SAME scale as input (int16-ranged floats)
+        outFramesGenerated.Should().BeGreaterThan(0, "Resampler should generate output frames");
+        inFramesConsumed.Should().Be((uint)inputFrames, "Resampler should consume all input");
+        
+        // Check output is not silent
+        int nonZeroCount = 0;
+        float maxAmp = 0;
+        for (int i = 0; i < (int)outFramesGenerated * 2; i++) {
+            float sample = Math.Abs(outputBuffer[i]);
+            if (sample > 0.0001f) {
+                nonZeroCount++;
+            }
+            if (sample > maxAmp) {
+                maxAmp = sample;
+            }
+        }
+        
+        float nonZeroPercent = outFramesGenerated > 0 ? (nonZeroCount * 100.0f / ((int)outFramesGenerated * 2)) : 0;","duplicate_id_conflict":false,"event_at":"2026-01-08T23:39:57+00:00","event_key":"inline_comment:2674264738","event_type":"inline_comment","html_url":null,"id":"2674264738","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"2e552a9f289fdaab17fc319c3bb8014efc6008af","original_line":null,"original_position":79,"original_start_line":null,"path":"tests/Spice86.Tests/Emulator/Devices/Sound/ResamplingDiagnosticTests.cs","position":79,"pull_request_review_id":"3641744280","pull_request_url":"https://api.github.com/repos/OpenRakis/Spice86/pulls/1766","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/openrakis/spice86/pull/1766","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"after_merge","updated_at":"2026-01-08T23:39:58Z","url":null,"user":"github-advanced-security[bot]","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"## Useless assignment to local variable

