+using System.Collections;
+using System.Collections.Specialized;
+
+namespace Spice;
+
+public partial class CollectionView
+{
+	/// <summary>
+	/// Returns collectionView.NativeView
+	/// </summary>
+	/// <param name="collectionView">The Spice.CollectionView</param>
+	public static implicit operator UICollectionView(CollectionView collectionView) => collectionView.NativeView;
+
+	/// <summary>
+	/// A view for presenting collections of data using a lambda-based item template.
+	/// Android -> AndroidX.RecyclerView.Widget.RecyclerView
+	/// iOS -> UIKit.UICollectionView
+	/// </summary>
+	public CollectionView() : base(v => new SpiceCollectionView((CollectionView)v) { AutoresizingMask = UIViewAutoresizing.None }) { }
+
+	/// <inheritdoc />
+	/// <param name="creator">Subclasses can pass in a Func to create a UIView</param>
+	protected CollectionView(Func<View, UIView> creator) : base(creator) { }
+
+	/// <summary>
+	/// The underlying UICollectionView
+	/// </summary>
+	public new UICollectionView NativeView => (UICollectionView)_nativeView.Value;
+
+	SpiceCollectionViewDataSource? _dataSource;
+	SpiceCollectionViewDelegate? _delegate;
+	INotifyCollectionChanged? _observableCollection;
+
+	partial void OnItemsSourceChanged(IEnumerable? value)
+	{
+		// Unsubscribe from old collection
+		if (_observableCollection != null)
+		{
+			_observableCollection.CollectionChanged -= OnCollectionChanged;
+			_observableCollection = null;
+		}
+
+		// Subscribe to new collection if it's observable
+		if (value is INotifyCollectionChanged observable)
+		{
+			_observableCollection = observable;
+			observable.CollectionChanged += OnCollectionChanged;
+		}
+
+		RefreshData();
+	}
+
+	partial void OnItemTemplateChanged(Func<object, View>? value)
+	{
+		RefreshData();
+	}
+
+	partial void OnOrientationChanged(Orientation value)
+	{
+		if (!_nativeView.IsValueCreated)
+			return;
+
+		var layout = (UICollectionViewFlowLayout)NativeView.CollectionViewLayout;
+		layout.ScrollDirection = value == Orientation.Horizontal
+			? UICollectionViewScrollDirection.Horizontal
+			: UICollectionViewScrollDirection.Vertical;
+
+		RefreshData();
+	}
+
+	partial void OnSelectionModeChanged(SelectionMode value)
+	{
+		if (!_nativeView.IsValueCreated)
+			return;
+
+		NativeView.AllowsSelection = value != SelectionMode.None;
+		NativeView.AllowsMultipleSelection = value == SelectionMode.Multiple;
+	}
+
+	partial void OnSelectedItemChanged(object? value)
+	{
+		if (!_nativeView.IsValueCreated || value == null)
+			return;
+","duplicate_id_conflict":false,"event_at":"2026-02-15T01:36:20+00:00","event_key":"inline_comment:2808250497","event_type":"inline_comment","html_url":null,"id":"2808250497","in_reply_to_id":"2808240171","is_feedback_candidate":true,"is_human":true,"line":null,"original_commit_id":"09f7b33ff6172e8ae99bbadf7dfad80bd4296d06","original_line":null,"original_position":84,"original_start_line":null,"path":"src/Spice/Platforms/iOS/CollectionView.cs","position":1,"pull_request_review_id":"3803042969","pull_request_url":"https://api.github.com/repos/jonathanpeppers/spice/pulls/103","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/jonathanpeppers/spice/pull/103","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-02-15T01:36:21Z","url":null,"user":"jonathanpeppers","user_id":null,"user_type":"User"}]

[{"author_association":null,"body":"@copilot should this be handled in the MemberExpression's update method instead? If the member name is mutated, is it possible to have the Update method create a new declaration instance or will that lead to issues?","body_updated_after_merge":false,"commit_id":"eb47e6cfb8f4ede2be846f0a97b1f2fff4797b22","created_at":"2026-03-25T15:37:46Z","diff_hunk":"@@ -101,6 +101,10 @@ public void Update(
                 _variable?.Update(name: name);
                 _asMember?.Update(memberName: name);
                 _declaration = null;
+                if (_asMember != null)
+                {
+                    _asMember.Declaration = Declaration;","duplicate_id_conflict":false,"event_at":"2026-03-25T15:37:46+00:00","event_key":"inline_comment:2989136943","event_type":"inline_comment","html_url":null,"id":"2989136943","in_reply_to_id":null,"is_feedback_candidate":true,"is_human":true,"line":null,"original_commit_id":"f31ee1416ed9698972417e1d858e800ffe5fb0d3","original_line":null,"original_position":6,"original_start_line":null,"path":"packages/http-client-csharp/generator/Microsoft.TypeSpec.Generator/src/Providers/FieldProvider.cs","position":6,"pull_request_review_id":"4007713117","pull_request_url":"https://api.github.com/repos/microsoft/typespec/pulls/10134","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/microsoft/typespec/pull/10134","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-03-25T15:39:22Z","url":null,"user":"jorgerangel-msft","user_id":null,"user_type":"User"},{"author_association":null,"body":"Creating a new `CodeWriterDeclaration` inside `MemberExpression.Update()` would lead to issues. The `FieldProvider` and `MemberExpression` must share the **same** `CodeWriterDeclaration` instance because:

1. `CodeWriter.WriteField(field)` uses `field.Declaration` and calls `SetActualName()` on that instance to record the deduped name
2. `MemberExpression.Write()` calls `writer.Append(Declaration)` → `GetActualName()` on the same instance to resolve it

If `MemberExpression.Update()` created its own instance, the CodeWriter would record the deduped name on the FieldProvider's instance, but MemberExpression would try to read from a different one (which wouldn't have the actual name set and would throw).

The `FieldProvider` needs to be the owner/source of truth for the declaration and push the shared instance to `MemberExpression`.","body_updated_after_merge":false,"commit_id":"eb47e6cfb8f4ede2be846f0a97b1f2fff4797b22","created_at":"2026-03-25T15:41:57Z","diff_hunk":"@@ -101,6 +101,10 @@ public void Update(
