+                if (_asMember != null)
+                {
+                    _asMember.Declaration = Declaration;","duplicate_id_conflict":false,"event_at":"2026-03-25T15:41:57+00:00","event_key":"inline_comment:2989174473","event_type":"inline_comment","html_url":null,"id":"2989174473","in_reply_to_id":"2989136943","is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"f31ee1416ed9698972417e1d858e800ffe5fb0d3","original_line":null,"original_position":6,"original_start_line":null,"path":"packages/http-client-csharp/generator/Microsoft.TypeSpec.Generator/src/Providers/FieldProvider.cs","position":6,"pull_request_review_id":"4007752252","pull_request_url":"https://api.github.com/repos/microsoft/typespec/pulls/10134","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/microsoft/typespec/pull/10134","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-03-25T15:41:57Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"@copilot this looks almost identical to the existing Append method. We should just update the existing method with an optional bool parameter","body_updated_after_merge":false,"commit_id":"250433652ee01c9806f580d4d2bbfde8db1d16df","created_at":"2026-03-25T16:54:37Z","diff_hunk":"@@ -1016,6 +1016,18 @@ internal void Append(CodeWriterDeclaration declaration)
