","body_updated_after_merge":false,"commit_id":"7687f4ce9a57ab8995950c5be0e2ca9017682baa","created_at":"2026-03-17T16:46:54Z","diff_hunk":"@@ -299,6 +300,26 @@ class ChatResponseAccessibleProvider extends Disposable implements IAccessibleVi
