+
+This is a simple example showing how `installed-check` works with a basic Node.js project.
+
+## What's in This Example
+
+This example uses:
+- `chalk@^4.0.0` - An older version to demonstrate version checking
+- `meow@^13.0.0` - A devDependency that may be flagged as unused
+
+## Usage
+
+```bash
+# From the repository root
+cd examples/basic
+npm install
+cd ../..
+
+# Run installed-check
+node cli-wrapper.cjs examples/basic
+```
+
+## Example Output
+
+<!-- BEGIN EXPECTED OUTPUT -->
+```
+Errors:
+
+knip: Narrower "engines.node" is needed: >=18.18.0","duplicate_id_conflict":false,"event_at":"2026-02-09T18:22:30+00:00","event_key":"inline_comment:2783960212","event_type":"inline_comment","html_url":null,"id":"2783960212","in_reply_to_id":null,"is_feedback_candidate":true,"is_human":true,"line":null,"original_commit_id":"8ad8f147bda474e4484908053a9e579140764211","original_line":null,"original_position":29,"original_start_line":null,"path":"examples/basic/README.md","position":1,"pull_request_review_id":"3774694833","pull_request_url":"https://api.github.com/repos/voxpelli/node-installed-check/pulls/118","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/voxpelli/node-installed-check/pull/118","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-02-09T18:27:42Z","url":null,"user":"voxpelli","user_id":null,"user_type":"User"},{"author_association":null,"body":"@copilot Introduce a proper error or warning as well here + also test running installed-check for the entire example workspace from its root, so that we demo that both ways works","body_updated_after_merge":false,"commit_id":"fa7092049967d0c295ecf0d373e78b50ab2125da","created_at":"2026-02-09T18:24:23Z","diff_hunk":"@@ -0,0 +1,55 @@
+# Monorepo Example
+
+This example demonstrates how `installed-check` automatically detects parent workspace roots in a monorepo setup.
+
+## Structure
+
+```
+monorepo/
+├── package.json (workspace root with chalk@^4.0.0 dependency)
+├── node_modules/ (shared dependencies installed here)
+└── packages/
+    ├── workspace-a/
+    │   └── package.json (depends on chalk@^4.0.0, has meow)
+    └── workspace-b/
+        └── package.json (depends on chalk@^4.0.0, has typescript in devDeps)
+```
+
+## Usage
+
+```bash
+# From the repository root, install dependencies
+cd examples/monorepo
+npm install
+cd ../..
+
+# Check workspace-a - automatically detects parent workspace
+node cli-wrapper.cjs examples/monorepo/packages/workspace-a
+
+# With debug output to see parent workspace detection
+node cli-wrapper.cjs --debug examples/monorepo/packages/workspace-a
+```
+
+## What Happens
+
+When you run `installed-check` in a workspace:
+1. **Parent detection**: It detects that `workspace-a` is part of the monorepo at `examples/monorepo`
+2. **Module resolution**: It uses the parent's `node_modules` for finding dependencies
+3. **Filtered checking**: It only checks the workspace package, not the parent
+4. **Shared dependencies**: Dependencies like `chalk` are found in the parent's `node_modules`
+
+The workspace passes all checks because the dependencies are correctly installed in the parent's `node_modules` and the parent workspace detection works properly.
+
+### Debug Output
+
+When run with `--debug`, you'll see information about parent workspace detection:
+
+<!-- BEGIN DEBUG OUTPUT -->
+```
+Parent workspace detection: Attempting to resolve parent workspace root
+Parent workspace detection: Found parent workspace root: /absolute/path/to/examples/monorepo
+Parent workspace detection: Using parent workspace root, filtering to current workspace
+```","duplicate_id_conflict":false,"event_at":"2026-02-09T18:24:23+00:00","event_key":"inline_comment:2783968414","event_type":"inline_comment","html_url":null,"id":"2783968414","in_reply_to_id":null,"is_feedback_candidate":true,"is_human":true,"line":null,"original_commit_id":"8ad8f147bda474e4484908053a9e579140764211","original_line":null,"original_position":52,"original_start_line":null,"path":"examples/monorepo/README.md","position":1,"pull_request_review_id":"3774694833","pull_request_url":"https://api.github.com/repos/voxpelli/node-installed-check/pulls/118","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/voxpelli/node-installed-check/pull/118","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-02-09T18:27:42Z","url":null,"user":"voxpelli","user_id":null,"user_type":"User"},{"author_association":null,"body":"@copilot Separate the generic README driven test comparison into an extractable JS-file so that we can reuse it in other projects – let this file be the project specific application of that separate file","body_updated_after_merge":false,"commit_id":"062725ec6eaf129e3dfd470213c8700e6ea7cc50","created_at":"2026-02-09T18:27:09Z","diff_hunk":"@@ -0,0 +1,229 @@
+/**
+ * Integration tests for installed-check examples
+ * This runs installed-check against the examples and validates the output
+ * against expected output blocks in the README files using unified/remark
+ */
+
+import { exec } from 'node:child_process';
+import { readFile } from 'node:fs/promises';
+import { promisify } from 'node:util';
+import { fileURLToPath } from 'node:url';
+import { dirname, join } from 'node:path';
+import { unified } from 'unified';
+import remarkParse from 'remark-parse';
+import { visit } from 'unist-util-visit';
+
+const execAsync = promisify(exec);
+const __dirname = dirname(fileURLToPath(import.meta.url));
+const rootDir = join(__dirname, '..');
+const cliPath = join(rootDir, 'cli-wrapper.cjs');
+
+let failed = false;
+
+/**
+ * Run a command and return stdout/stderr
+ *
+ * @param {string} command
+ * @returns {Promise<{code: number, output: string, stderr: string, stdout: string}>}
+ */
+async function run (command) {
+  try {
+    const { stderr, stdout } = await execAsync(command, { cwd: rootDir });
+    return { code: 0, output: stdout + stderr, stderr, stdout };
+  } catch (err) {
+    return {
+      code: err.code || 1,
+      output: (err.stdout || '') + (err.stderr || ''),
+      stderr: err.stderr || '',
+      stdout: err.stdout || '',
+    };
+  }
+}
+
+/**
+ * Extract expected output from README markdown using unified/remark
+ *
+ * @param {string} readmePath
+ * @param {string} marker
+ * @returns {Promise<string | undefined>}
+ */
+async function extractExpectedOutput (readmePath, marker = 'EXPECTED OUTPUT') {
+  const content = await readFile(readmePath, 'utf8');
+  const tree = unified().use(remarkParse).parse(content);
+
+  let foundMarker = false;
+  let codeBlockContent;
+
+  visit(tree, (node) => {
+    // Look for HTML comments marking the section
+    if (node.type === 'html' && node.value.includes(`BEGIN ${marker}`)) {
+      foundMarker = true;
+      return;
+    }
+
+    if (node.type === 'html' && node.value.includes(`END ${marker}`)) {
+      foundMarker = false;
+      return;
+    }
+
+    // If we're in the marked section and find a code block, extract it
+    if (foundMarker && node.type === 'code') {
+      codeBlockContent = node.value;
+      return 'skip';
+    }
+  });
+
+  return codeBlockContent;
+}
+
+/**
+ * Normalize output for comparison (remove paths, etc)
+ *
+ * @param {string} output
+ * @returns {string}
+ */
+function normalizeOutput (output) {
+  return output
+    .replaceAll(/\/\S+\/examples\//g, '/absolute/path/to/examples/')
+    .trim();
+}
+
+/**
+ * Test helper
+ *
+ * @param {string} name
+ * @param {() => Promise<void>} fn
+ */
+async function test (name, fn) {
+  process.stdout.write(`  ${name} ... `);
+  try {
+    await fn();
+    // eslint-disable-next-line no-console
+    console.log('✓');
+  } catch (err) {
+    // eslint-disable-next-line no-console
+    console.log('✗');
+    // eslint-disable-next-line no-console
+    console.error(`    Error: ${err.message}`);
+    failed = true;
+  }
+}
+
+/**
+ * Assert helper
+ *
+ * @param {boolean} condition
+ * @param {string} message
+ */
+function assert (condition, message) {
+  if (!condition) {
+    throw new Error(message);
+  }
+}
+
+// eslint-disable-next-line no-console
+console.log('\nIntegration Tests\n');","duplicate_id_conflict":false,"event_at":"2026-02-09T18:27:09+00:00","event_key":"inline_comment:2783980073","event_type":"inline_comment","html_url":null,"id":"2783980073","in_reply_to_id":null,"is_feedback_candidate":true,"is_human":true,"line":null,"original_commit_id":"8ad8f147bda474e4484908053a9e579140764211","original_line":null,"original_position":125,"original_start_line":null,"path":"test/integration.js","position":1,"pull_request_review_id":"3774694833","pull_request_url":"https://api.github.com/repos/voxpelli/node-installed-check/pulls/118","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/voxpelli/node-installed-check/pull/118","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-02-09T18:27:42Z","url":null,"user":"voxpelli","user_id":null,"user_type":"User"},{"author_association":null,"body":"Fixed in commit 062725e. The issue was a critical bug where `cwd` was undefined when not using parent workspace detection, causing installed-check to fall back to `process.cwd()` and incorrectly check dependencies from the command execution directory. The fix ensures `cwd` is always set to the resolved directory. Examples now show correct output with no spurious knip errors.","body_updated_after_merge":false,"commit_id":"fa7092049967d0c295ecf0d373e78b50ab2125da","created_at":"2026-02-09T18:40:59Z","diff_hunk":"@@ -0,0 +1,37 @@
