+/**
+ * Integration tests for installed-check examples
+ * This runs installed-check against the examples and validates the output
+ * against expected output blocks in the README files using unified/remark
+ */
+
+import { exec } from 'node:child_process';
+import { readFile } from 'node:fs/promises';
+import { promisify } from 'node:util';
+import { fileURLToPath } from 'node:url';
+import { dirname, join } from 'node:path';
+import { unified } from 'unified';
+import remarkParse from 'remark-parse';
+import { visit } from 'unist-util-visit';
+
+const execAsync = promisify(exec);
+const __dirname = dirname(fileURLToPath(import.meta.url));
+const rootDir = join(__dirname, '..');
+const cliPath = join(rootDir, 'cli-wrapper.cjs');
+
+let failed = false;
+
+/**
+ * Run a command and return stdout/stderr
+ *
+ * @param {string} command
+ * @returns {Promise<{code: number, output: string, stderr: string, stdout: string}>}
+ */
+async function run (command) {
+  try {
+    const { stderr, stdout } = await execAsync(command, { cwd: rootDir });
+    return { code: 0, output: stdout + stderr, stderr, stdout };
+  } catch (err) {
+    return {
+      code: err.code || 1,
+      output: (err.stdout || '') + (err.stderr || ''),
+      stderr: err.stderr || '',
+      stdout: err.stdout || '',
+    };
+  }
+}
+
+/**
+ * Extract expected output from README markdown using unified/remark
+ *
+ * @param {string} readmePath
+ * @param {string} marker
+ * @returns {Promise<string | undefined>}
+ */
+async function extractExpectedOutput (readmePath, marker = 'EXPECTED OUTPUT') {
+  const content = await readFile(readmePath, 'utf8');
+  const tree = unified().use(remarkParse).parse(content);
+
+  let foundMarker = false;
+  let codeBlockContent;
+
+  visit(tree, (node) => {
+    // Look for HTML comments marking the section
+    if (node.type === 'html' && node.value.includes(`BEGIN ${marker}`)) {
+      foundMarker = true;
+      return;
+    }
+
+    if (node.type === 'html' && node.value.includes(`END ${marker}`)) {
+      foundMarker = false;
+      return;
+    }
+
+    // If we're in the marked section and find a code block, extract it
+    if (foundMarker && node.type === 'code') {
+      codeBlockContent = node.value;
+      return 'skip';
+    }
+  });
+
+  return codeBlockContent;
+}
+
+/**
+ * Normalize output for comparison (remove paths, etc)
+ *
+ * @param {string} output
+ * @returns {string}
+ */
+function normalizeOutput (output) {
+  return output
+    .replaceAll(/\/\S+\/examples\//g, '/absolute/path/to/examples/')
+    .trim();
+}
+
+/**
+ * Test helper
+ *
+ * @param {string} name
+ * @param {() => Promise<void>} fn
+ */
+async function test (name, fn) {
+  process.stdout.write(`  ${name} ... `);
+  try {
+    await fn();
+    // eslint-disable-next-line no-console
+    console.log('✓');
+  } catch (err) {
+    // eslint-disable-next-line no-console
+    console.log('✗');
+    // eslint-disable-next-line no-console
+    console.error(`    Error: ${err.message}`);
+    failed = true;
+  }
+}
+
+/**
+ * Assert helper
+ *
+ * @param {boolean} condition
+ * @param {string} message
+ */
+function assert (condition, message) {
+  if (!condition) {
+    throw new Error(message);
+  }
+}
+
+// eslint-disable-next-line no-console
+console.log('\nIntegration Tests\n');","duplicate_id_conflict":false,"event_at":"2026-02-09T18:41:08+00:00","event_key":"inline_comment:2784048370","event_type":"inline_comment","html_url":null,"id":"2784048370","in_reply_to_id":"2783980073","is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"8ad8f147bda474e4484908053a9e579140764211","original_line":null,"original_position":125,"original_start_line":null,"path":"test/integration.js","position":1,"pull_request_review_id":"3774786739","pull_request_url":"https://api.github.com/repos/voxpelli/node-installed-check/pulls/118","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/voxpelli/node-installed-check/pull/118","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-02-09T18:41:08Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"@copilot Empty output is a baaaaad demo. Produce some representable errors","body_updated_after_merge":false,"commit_id":"463880e041852807647d4fddd4f6107cf34eb193","created_at":"2026-02-09T18:45:42Z","diff_hunk":"@@ -0,0 +1,33 @@
