[{"author_association":null,"body":"`function_exists('curl_init')` doesn’t guarantee `curl_init($url)` returns a valid CurlHandle. If `curl_init` returns `false` (e.g., malformed/empty URL), the subsequent `curl_setopt` calls will raise a TypeError and bypass the retry/exception flow. Handle the `false` return explicitly (set an error message and either retry or fall back to `file_get_contents`).","body_updated_after_merge":false,"commit_id":"c6afaf5b31ffab046e234b073214f4b5a9d2475b","created_at":"2026-03-02T21:12:42Z","diff_hunk":"@@ -245,30 +245,50 @@ public static function downloadRelease(ChurchCRMRelease $release): array
