+        $lastErrorMsg = 'Unknown error';

         for ($attempt = 1; $attempt <= $maxAttempts; $attempt++) {
             $logger->info('Download attempt ' . $attempt . ' of ' . $maxAttempts);

-            // Clear any previous error
-            @error_clear_last();
-
-            $downloadContent = @file_get_contents($url);
