[{"author_association":null,"body":"The content size calculation may not work correctly for all scenarios. When Orientation is Horizontal, the height is set to NativeView.Frame.Height, but if the ScrollView hasn't been laid out yet, Frame.Height could be 0. Similarly for Vertical orientation with Frame.Width. Consider alternative approaches such as allowing both dimensions to scroll with appropriate constraints, or deferring size calculation until the frame is valid.","body_updated_after_merge":false,"commit_id":"05377c3699a70b323d6a00a992742ea6ba5d8a92","created_at":"2026-02-14T03:16:18Z","diff_hunk":"@@ -0,0 +1,91 @@
+namespace Spice;
+
+public partial class ScrollView
+{
+	/// <summary>
+	/// Returns scrollView.NativeView
+	/// </summary>
+	/// <param name="scrollView">The Spice.ScrollView</param>
+	public static implicit operator UIScrollView(ScrollView scrollView) => scrollView.NativeView;
+
+	/// <summary>
+	/// A scrollable container view that can hold a single child view.
+	/// Android -> Android.Widget.ScrollView / Android.Widget.HorizontalScrollView
+	/// iOS -> UIKit.UIScrollView
+	/// </summary>
