+namespace Spice;
+
+public partial class ScrollView
+{
+	/// <summary>
+	/// Returns scrollView.NativeView
+	/// </summary>
+	/// <param name="scrollView">The Spice.ScrollView</param>
+	public static implicit operator UIScrollView(ScrollView scrollView) => scrollView.NativeView;
+
+	/// <summary>
+	/// A scrollable container view that can hold a single child view.
+	/// Android -> Android.Widget.ScrollView / Android.Widget.HorizontalScrollView
+	/// iOS -> UIKit.UIScrollView
+	/// </summary>
+	public ScrollView() : base(v => new SpiceScrollView((ScrollView)v) { AutoresizingMask = UIViewAutoresizing.None }) { }
+
+	/// <inheritdoc />
+	/// <param name="frame">Pass the underlying view a frame</param>
+	public ScrollView(CGRect frame) : base(v => new SpiceScrollView((ScrollView)v, frame) { AutoresizingMask = UIViewAutoresizing.None }) { }
+
+	/// <inheritdoc />
+	/// <param name="creator">Subclasses can pass in a Func to create a UIView</param>
+	protected ScrollView(Func<View, UIView> creator) : base(creator) { }
+
+	/// <summary>
+	/// The underlying UIScrollView
+	/// </summary>
+	public new UIScrollView NativeView => (UIScrollView)_nativeView.Value;
+
+	partial void OnOrientationChanging(Orientation value)
+	{
+		// iOS UIScrollView supports both directions simultaneously by default
+		// We can optionally restrict scrolling direction if needed
+	}
+
+	/// <inheritdoc />
+	protected override void AddSubview(View view)
+	{
+		// ScrollView should only have one child
+		// Remove all existing children first
+		foreach (UIView subview in NativeView.Subviews)
+		{
+			subview.RemoveFromSuperview();
+		}
+
+		NativeView.AddSubview(view);
+		view.UpdateAlign();
+
+		// Update content size based on child
+		UpdateContentSize(view);
+	}
+
+	void UpdateContentSize(View view)
+	{
+		var childView = (UIView)view;
+		childView.SizeToFit();
+		var size = childView.Frame.Size;
+
+		if (Orientation == Orientation.Horizontal)
+		{
+			// Allow horizontal scrolling, constrain vertical
+			NativeView.ContentSize = new CGSize(size.Width, NativeView.Frame.Height);
+		}
+		else // Vertical
+		{
+			// Allow vertical scrolling, constrain horizontal
+			NativeView.ContentSize = new CGSize(NativeView.Frame.Width, size.Height);
+		}","duplicate_id_conflict":false,"event_at":"2026-02-14T04:56:18+00:00","event_key":"inline_comment:2807004556","event_type":"inline_comment","html_url":null,"id":"2807004556","in_reply_to_id":"2806872878","is_feedback_candidate":true,"is_human":true,"line":null,"original_commit_id":"de4293cc1cbbf2a0608a0c4fb3a7275efb236983","original_line":null,"original_position":69,"original_start_line":null,"path":"src/Spice/Platforms/iOS/ScrollView.cs","position":93,"pull_request_review_id":"3800878791","pull_request_url":"https://api.github.com/repos/jonathanpeppers/spice/pulls/78","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/jonathanpeppers/spice/pull/78","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-02-14T04:56:18Z","url":null,"user":"jonathanpeppers","user_id":null,"user_type":"User"},{"author_association":null,"body":"Addressed in 9db1c70. Removed the duplicate test and added `AddingMultipleChildrenTracksAll` which verifies that the `Children` collection tracks all added children. On iOS the native `AddSubview` override removes previous UIView subviews (single-child constraint at the native level), but the `Children` ObservableCollection retains all items — this matches how the base View works.","body_updated_after_merge":false,"commit_id":"05377c3699a70b323d6a00a992742ea6ba5d8a92","created_at":"2026-02-14T04:56:26Z","diff_hunk":"@@ -0,0 +1,78 @@
+namespace Spice.Tests;
+
+/// <summary>
+/// Tests for ScrollView functionality
+/// </summary>
+public class ScrollViewTests
+{
+	[Fact]
+	public void CanCreate()
+	{
+		var scrollView = new ScrollView();
+		Assert.NotNull(scrollView);
+	}
+
+	[Fact]
+	public void DefaultOrientationIsVertical()
+	{
+		var scrollView = new ScrollView();
+		Assert.Equal(Orientation.Vertical, scrollView.Orientation);
+	}
+
+	[Fact]
+	public void CanSetOrientation()
+	{
+		var scrollView = new ScrollView
+		{
+			Orientation = Orientation.Horizontal
+		};
+		Assert.Equal(Orientation.Horizontal, scrollView.Orientation);
+	}
+
+	[Fact]
+	public void CanSetOrientationViaPropertyInitializer()
+	{
+		// This tests the Android limitation where Orientation must be set before native view creation
+		var scrollView = new ScrollView { Orientation = Orientation.Horizontal };
+		Assert.Equal(Orientation.Horizontal, scrollView.Orientation);
+	}
+
+	[Fact]
+	public void CanAddChild()
+	{
+		var scrollView = new ScrollView();
+		var label = new Label { Text = "Test" };
+		scrollView.Add(label);
+		
+		Assert.Single(scrollView.Children);
+		Assert.Equal(label, scrollView.Children[0]);
+	}
+
+	[Fact]
+	public void PropertyChangedFiresOnOrientationChange()
+	{
+		string? property = null;
+		var scrollView = new ScrollView();
+		scrollView.PropertyChanged += (sender, e) => property = e.PropertyName;
+		scrollView.Orientation = Orientation.Horizontal;
+
+		Assert.Equal(nameof(scrollView.Orientation), property);
+	}
+
+	[Fact]
+	public void CanContainStackView()
+	{
+		var scrollView = new ScrollView();
+		var stackView = new StackView
+		{
+			new Label { Text = "Item 1" },
+			new Label { Text = "Item 2" },
+			new Label { Text = "Item 3" }
+		};
+		scrollView.Add(stackView);
+		
+		Assert.Single(scrollView.Children);
+		Assert.Equal(stackView, scrollView.Children[0]);
+		Assert.Equal(3, stackView.Children.Count);
+	}","duplicate_id_conflict":false,"event_at":"2026-02-14T04:56:26+00:00","event_key":"inline_comment:2807004794","event_type":"inline_comment","html_url":null,"id":"2807004794","in_reply_to_id":"2806872886","is_feedback_candidate":true,"is_human":true,"line":null,"original_commit_id":"de4293cc1cbbf2a0608a0c4fb3a7275efb236983","original_line":null,"original_position":77,"original_start_line":null,"path":"tests/Spice.Tests/ScrollViewTests.cs","position":84,"pull_request_review_id":"3800879397","pull_request_url":"https://api.github.com/repos/jonathanpeppers/spice/pulls/78","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/jonathanpeppers/spice/pull/78","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-02-14T04:56:26Z","url":null,"user":"jonathanpeppers","user_id":null,"user_type":"User"},{"author_association":null,"body":"Fixed in 9db1c70. Completely redesigned the Android approach — instead of trying to reassign the readonly `_nativeView`, the orientation is now resolved at construction time via `GetCreator(orientation)` which selects the correct native type. `OnOrientationChanging` simply throws `NotSupportedException` directing users to the `ScrollView(Orientation)` constructor.","body_updated_after_merge":false,"commit_id":"de4293cc1cbbf2a0608a0c4fb3a7275efb236983","created_at":"2026-02-14T04:56:32Z","diff_hunk":"@@ -0,0 +1,64 @@
+using Android.Content;
+
+namespace Spice;
+
+public partial class ScrollView
+{
+	/// <summary>
+	/// Returns scrollView.NativeView
+	/// </summary>
+	/// <param name="scrollView">The Spice.ScrollView</param>
+	public static implicit operator Android.Widget.ScrollView(ScrollView scrollView) => (Android.Widget.ScrollView)scrollView._nativeView.Value;
+
+	static Android.Widget.ScrollView CreateVertical(Context context) => new(context);
+
+	static HorizontalScrollView CreateHorizontal(Context context) => new(context);
+
+	/// <summary>
+	/// A scrollable container view that can hold a single child view.
+	/// Android -> Android.Widget.ScrollView (vertical) / Android.Widget.HorizontalScrollView (horizontal)
+	/// iOS -> UIKit.UIScrollView
+	/// </summary>
+	public ScrollView() : this(Platform.Context, CreateVertical) { }
+
+	/// <inheritdoc />
+	/// <param name="context">Option to pass the desired Context, otherwise Platform.Context is used</param>
+	public ScrollView(Context context) : this(context, CreateVertical) { }
+
+	/// <inheritdoc />
+	/// <param name="creator">Subclasses can pass in a Func to create a Android.Views.View</param>
+	protected ScrollView(Func<Context, Android.Views.View> creator) : this(Platform.Context, creator) { }
+
+	/// <inheritdoc />
+	/// <param name="context">Option to pass the desired Context, otherwise Platform.Context is used</param>
+	/// <param name="creator">Subclasses can pass in a Func to create a Android.Views.View</param>
+	protected ScrollView(Context context, Func<Context, Android.Views.View> creator) : base(context, creator) { }
+
+	/// <summary>
+	/// The underlying Android.Widget.ScrollView (or HorizontalScrollView)
+	/// </summary>
+	public new Android.Views.ViewGroup NativeView => (Android.Views.ViewGroup)_nativeView.Value;
+
+	partial void OnOrientationChanging(Orientation value)
+	{
+		// Note: Changing orientation after creation requires recreating the native view
+		// Android has separate ScrollView (vertical) and HorizontalScrollView classes
+		// This is a limitation of Android's API design
+		// The Orientation property should be set before the native view is created
+		// (i.e., before accessing NativeView or Children)
+		if (_nativeView.IsValueCreated)
+		{
+			throw new NotSupportedException("Changing ScrollView orientation after creation is not supported on Android. Set Orientation before accessing NativeView or adding children.");
+		}
+
+		// Update the creator function to use the correct type
+		_nativeView = new Lazy<Android.Views.View>(() =>
+		{
+			var view = value == Orientation.Horizontal
+				? (Android.Views.View)CreateHorizontal(Platform.Context)
+				: (Android.Views.View)CreateVertical(Platform.Context);
+			view.LayoutParameters = _layoutParameters.Value;
+			return view;
+		});","duplicate_id_conflict":false,"event_at":"2026-02-14T04:56:32+00:00","event_key":"inline_comment:2807004986","event_type":"inline_comment","html_url":null,"id":"2807004986","in_reply_to_id":"2806872894","is_feedback_candidate":true,"is_human":true,"line":null,"original_commit_id":"de4293cc1cbbf2a0608a0c4fb3a7275efb236983","original_line":null,"original_position":62,"original_start_line":null,"path":"src/Spice/Platforms/Android/ScrollView.cs","position":1,"pull_request_review_id":"3800879822","pull_request_url":"https://api.github.com/repos/jonathanpeppers/spice/pulls/78","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/jonathanpeppers/spice/pull/78","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-02-14T04:56:32Z","url":null,"user":"jonathanpeppers","user_id":null,"user_type":"User"},{"author_association":null,"body":"Fixed in 9db1c70. Changed the implicit operator return type to `Android.Views.ViewGroup` which is the common base of both `ScrollView` and `HorizontalScrollView`.","body_updated_after_merge":false,"commit_id":"de4293cc1cbbf2a0608a0c4fb3a7275efb236983","created_at":"2026-02-14T04:56:37Z","diff_hunk":"@@ -0,0 +1,64 @@
