            try {
                var newChart = echarts.init(container, newTheme);
                this.chart = newChart;
                this.updateOption();
                this.resize();
            } catch (e) {
                // On any error during re-initialization, ensure chart reference
                // remains in a consistent state (null)
                this.chart = null;
