+                  .allowOverride(assignmentOptions.getAllowOverride())
+                  .action(assignmentOptions.getAction());
+        }
+
+        return performAssignment(userTaskKey, request);
+      }
+    } catch (final Exception e) {
+      return CallToolResultMapper.mapErrorToResult(e);
+    }
