    /**
     * Convert an ASN.1/DER-encoded ECDSA signature to the raw R||S format (P-1363).
     *
     * @param string $derSignature DER-encoded ECDSA signature
     * @param int    $partLength   Length of R and S in bytes (32 for P-256)
     */
    private function convertDerToP1363Signature(string $derSignature, int $partLength): string
    {
        $offset = 0;
        $der = $derSignature;
        $length = \strlen($der);

        if ($length < 8 || \ord($der[$offset++]) !== 0x30) {
            throw new \RuntimeException('Invalid DER signature: expected SEQUENCE.');
        }

        $seqLength = \ord($der[$offset++]);
        if ($seqLength & 0x80) {
            $numBytes = $seqLength & 0x1F;
            if ($numBytes === 0 || $numBytes > 2 || $offset + $numBytes > $length) {
                throw new \RuntimeException('Invalid DER signature: bad SEQUENCE length.');
            }
            $seqLength = 0;
            for ($i = 0; $i < $numBytes; $i++) {
                $seqLength = ($seqLength << 8) | \ord($der[$offset++]);
            }
        }

        if ($offset >= $length || \ord($der[$offset++]) !== 0x02) {
            throw new \RuntimeException('Invalid DER signature: expected INTEGER for R.');
        }

        $rLength = \ord($der[$offset++]);
        if ($rLength & 0x80) {
            $numBytes = $rLength & 0x1F;
            if ($numBytes === 0 || $numBytes > 2 || $offset + $numBytes > $length) {
                throw new \RuntimeException('Invalid DER signature: bad R length.');
            }
            $rLength = 0;
            for ($i = 0; $i < $numBytes; $i++) {
                $rLength = ($rLength << 8) | \ord($der[$offset++]);
            }
        }

        if ($offset + $rLength > $length) {
            throw new \RuntimeException('Invalid DER signature: R value truncated.');
        }

        $r = \substr($der, $offset, $rLength);
        $offset += $rLength;

        if ($offset >= $length || \ord($der[$offset++]) !== 0x02) {
            throw new \RuntimeException('Invalid DER signature: expected INTEGER for S.');
        }

        $sLength = \ord($der[$offset++]);
        if ($sLength & 0x80) {
            $numBytes = $sLength & 0x1F;
            if ($numBytes === 0 || $numBytes > 2 || $offset + $numBytes > $length) {
                throw new \RuntimeException('Invalid DER signature: bad S length.');
            }
            $sLength = 0;
            for ($i = 0; $i < $numBytes; $i++) {
                $sLength = ($sLength << 8) | \ord($der[$offset++]);
            }
        }

        if ($offset + $sLength > $length) {
            throw new \RuntimeException('Invalid DER signature: S value truncated.');
        }

        $s = \substr($der, $offset, $sLength);

        $r = \ltrim($r, "\x00");
        $s = \ltrim($s, "\x00");

        if (\strlen($r) > $partLength || \strlen($s) > $partLength) {
            throw new \RuntimeException('Invalid DER signature: R or S too long.');
        }

        $r = \str_pad($r, $partLength, "\x00", STR_PAD_LEFT);
        $s = \str_pad($s, $partLength, "\x00", STR_PAD_LEFT);

        return $r.$s;
    }
