+    {
+        $teamId = $this->config->get('team_id');
+        $keyId = $this->config->get('key_id');
+        $privateKey = $this->config->get('private_key');
+
+        $header = $this->base64UrlEncode(\json_encode(['kid' => $keyId, 'alg' => 'ES256']));
