+    private async void TranslationTimer_Tick(object? sender, EventArgs e)
+    {
+        translationTimer.Stop();
+
+        if (!isTranslationEnabled || !WindowsAiUtilities.CanDeviceUseWinAI())
+            return;
+
+        await PerformTranslationAsync();
