+		$allowed      = rtrim( $allowed, DIRECTORY_SEPARATOR );
+		$real_allowed = realpath( $allowed );
+		if ( false !== $real_allowed ) {
+			$allowed = $real_allowed;
+		}
+		// Check if path starts with allowed directory
+		// On Windows, use case-insensitive comparison as filesystem paths are case-insensitive
+		$is_windows = DIRECTORY_SEPARATOR === '\\';","duplicate_id_conflict":false,"event_at":"2026-03-12T08:25:13+00:00","event_key":"inline_comment:2923016638","event_type":"inline_comment","html_url":null,"id":"2923016638","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"8af9eca55e7a5e11a28d63f16f176c4bfb9237f4","original_line":null,"original_position":35,"original_start_line":null,"path":"php/utils.php","position":1,"pull_request_review_id":"3934751447","pull_request_url":"https://api.github.com/repos/wp-cli/wp-cli/pulls/6192","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/wp-cli/wp-cli/pull/6192","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-03-12T08:25:14Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"The new normalization block calls realpath($dir) before checking open_basedir. If the starting $dir is outside open_basedir (e.g. CWD not in the allowed list), realpath() itself can trigger the same open_basedir warning this PR is trying to avoid. Consider only calling realpath() after confirming the directory is within open_basedir (and preferably readable), or switching to a pure string normalization (e.g. normalize_path()) that won't touch the filesystem.","body_updated_after_merge":false,"commit_id":"b9e8cba6a56c2f8067f5d55afb91da0f1fbbb6af","created_at":"2026-03-12T08:25:14Z","diff_hunk":"@@ -230,7 +273,15 @@ function find_file_upward( $files, $dir = null, $stop_check = null ) {
