+		/// <returns>true if the target is alive and was successfully cast to type T; otherwise, false.</returns>
+		public bool TryGetTarget<T>(out T target) where T : class
+		{
+			target = default;
+
+			// Return false if disposed, without throwing
+			if (_disposed)
+			{
+				return false;
+			}
+
+			// Get the target once and check if it's alive
+			var rawTarget = _targetHandle?.Target;
+			if (rawTarget == null || !IsNativeAlive(rawTarget))
+			{
+				return false;
+			}
+
+			// Try to cast to the requested type
+			if (rawTarget is T castTarget)
+			{
+				target = castTarget;
+				return true;
+			}
+
+			return false;
+		}","duplicate_id_conflict":false,"event_at":"2026-03-02T16:25:51+00:00","event_key":"inline_comment:2873376144","event_type":"inline_comment","html_url":null,"id":"2873376144","in_reply_to_id":null,"is_feedback_candidate":false,"is_human":false,"line":null,"original_commit_id":"9e7114df3e467df11e7ed7ffe2a5d113f3d417e0","original_line":null,"original_position":35,"original_start_line":null,"path":"src/Uno.UI/DataBinding/ManagedWeakReference.cs","position":43,"pull_request_review_id":"3877235564","pull_request_url":"https://api.github.com/repos/unoplatform/uno/pulls/22345","side":null,"source_table":"pr_review_comments","source_url":"https://github.com/unoplatform/uno/pull/22345","start_line":null,"start_side":null,"state":null,"submitted_at":null,"temporal_relation":"during_pr","updated_at":"2026-03-02T16:25:52Z","url":null,"user":"Copilot","user_id":null,"user_type":"Bot"},{"author_association":null,"body":"`CreateWeakReferenceToCollectedObject` is small enough that it may be inlined, which can extend the lifetime of `target` and make `When_TryGetTarget_With_Collected_Target` flaky (object may not become collectible, so the test can intermittently fail). Consider preventing inlining (e.g., `MethodImplOptions.NoInlining`) and/or using an explicit scope that ensures no strong references remain before forcing GC.","body_updated_after_merge":false,"commit_id":"ebbf10d37087366c2e8a3fb57bc0b909c76a6113","created_at":"2026-03-02T16:25:51Z","diff_hunk":"@@ -198,6 +198,88 @@ public void When_Null_Target_And_Owner()
